    ('b58a0a2e-6a61-513a-b8eb-79a33cad8bf4'::uuid, 'emc', '4e', 'Le respect de la vie privée et l’identité numérique', 'Parmi ces traces, laquelle fait partie de ce que les services enregistrent sans qu’on le voie ?', 'mcq', '["Une photo qu’on publie","Nos recherches et notre position","Un message envoyé à un ami","Une vidéo où un camarade nous identifie"]'::jsonb, 1, 'Recherches, position, temps passé, achats : cette troisième couche de l’identité numérique est enregistrée sans qu’on s’en rende compte.', 1),
    ('01bb92e1-dfeb-522d-ad85-a75723c13ba6'::uuid, 'emc', '4e', 'Le respect de la vie privée et l’identité numérique', 'En quelle année le RGPD est-il entré en application ?', 'mcq', '["2004","2010","2018","2022"]'::jsonb, 2, 'Le règlement général sur la protection des données s’applique depuis 2018 dans toute l’Union européenne.', 2),
    ('cde6198b-10e8-5329-8a2f-2cf25304e355'::uuid, 'emc', '4e', 'Le respect de la vie privée et l’identité numérique', 'Comment s’appelle le droit de demander qu’on supprime ses données ?', 'mcq', '["Le droit à l’effacement, ou « droit à l’oubli »","Le droit d’accès","Le droit de rectification","Le droit de réponse"]'::jsonb, 0, 'Le RGPD prévoit l’accès, la rectification, l’opposition et l’effacement, dit « droit à l’oubli ».', 3),
    ('6eae5121-c8ff-5ce2-a03e-19860043e215'::uuid, 'emc', '4e', 'Le respect de la vie privée et l’identité numérique', 'Avant 15 ans en France, que faut-il pour qu’un service traite ses données ?', 'mcq', '["Rien de particulier","Une carte d’identité","L’accord de la CNIL","L’accord d’un parent"]'::jsonb, 3, 'L’âge du consentement autonome est fixé à 15 ans ; en dessous, l’accord d’un parent est nécessaire.', 4),
    ('1a6e4ef2-1112-50da-b3a2-324b016d7564'::uuid, 'emc', '5e', 'La liberté d’expression et ses limites', 'Quelle est la différence entre l’injure et la diffamation ?', 'mcq', '["L’injure est écrite, la diffamation orale","L’injure est une expression outrageante sans fait précis, la diffamation affirme un fait faux","L’injure vise un groupe, la diffamation un parti","Il n’y en a aucune"]'::jsonb, 1, 'L’injure outrage sans rien affirmer de précis ; la diffamation attribue un fait faux qui porte atteinte à l’honneur.', 1),
    ('05eaf427-5e10-5bc0-9dff-9a9e3a80c76c'::uuid, 'emc', '5e', 'La liberté d’expression et ses limites', 'Quel article de la Déclaration de 1789 pose la libre communication des pensées ?', 'mcq', '["L’article 1","L’article 16","L’article 11","L’article 9"]'::jsonb, 2, 'L’article 11 fait de la libre communication des pensées et des opinions l’un des droits les plus précieux.', 2),
    ('8d391d27-3742-52a0-ae29-dd2f34d26906'::uuid, 'emc', '5e', 'La liberté d’expression et ses limites', 'Qu’est-ce qui permet de retrouver l’auteur d’un message posté sous pseudonyme ?', 'mcq', '["L’adresse IP","Le nombre d’abonnés","La photo de profil","Rien, le pseudonyme protège"]'::jsonb, 0, 'Un message en ligne est traçable par l’adresse IP : le pseudonyme ne garantit pas l’anonymat devant la justice.', 3),
    ('dbe5f596-166d-5972-bc5e-f072407d63ff'::uuid, 'emc', '5e', 'La liberté d’expression et ses limites', 'Présenter favorablement un acte terroriste, c’est commettre…', 'mcq', '["une diffamation","une injure","un harcèlement","une apologie du terrorisme"]'::jsonb, 3, 'L’apologie du terrorisme est un délit : elle fait partie des limites légales de la liberté d’expression.', 4),
    ('9148e08f-fe6e-591c-b504-5a103a434145'::uuid, 'emc', '4e', 'Voter : le droit de vote et les élections', 'Depuis quand l’isoloir et l’enveloppe garantissent-ils le secret du vote ?', 'mcq', '["1848","1913","1944","1974"]'::jsonb, 1, 'L’isoloir et l’enveloppe sont imposés en 1913 : ils protègent l’électeur de toute pression.', 1),
    ('52eaf88f-69f0-53a7-b64f-8e0a8e492eea'::uuid, 'emc', '4e', 'Voter : le droit de vote et les élections', 'Pour combien de temps les députés sont-ils élus ?', 'mcq', '["6 ans","7 ans","5 ans","4 ans"]'::jsonb, 2, 'Les députés, comme le président de la République et les députés européens, sont élus pour 5 ans ; les conseillers municipaux pour 6 ans.', 2),
    ('03206587-3517-5451-b4dd-228a4961a3ca'::uuid, 'emc', '4e', 'Voter : le droit de vote et les élections', 'Quel est l’avantage principal du scrutin majoritaire ?', 'mcq', '["Il dégage des majorités nettes","Il représente parfaitement toutes les opinions","Il supprime l’abstention","Il rend le vote obligatoire"]'::jsonb, 0, 'Le majoritaire donne des majorités claires, mais laisse des voix sans représentation ; le proportionnel fait l’inverse.', 3),
    ('9d74a025-5e02-5cae-acad-4ddbe9b96984'::uuid, 'emc', '4e', 'Voter : le droit de vote et les élections', 'Qu’est-ce qu’un vote nul ?', 'mcq', '["Une enveloppe vide","Une abstention","Un vote par procuration","Un bulletin abîmé ou raturé"]'::jsonb, 3, 'Le vote nul est un bulletin abîmé ou raturé ; l’enveloppe vide est un vote blanc.', 4),
    ('9162ac15-cc08-5f1e-93ac-e1ae8da9655e'::uuid, 'emc', '5e', 'Voter : le droit de vote et les élections', 'Depuis quand l’isoloir et l’enveloppe garantissent-ils le secret du vote ?', 'mcq', '["1848","1913","1944","1974"]'::jsonb, 1, 'L’isoloir et l’enveloppe sont imposés en 1913 : ils protègent l’électeur de toute pression.', 1),
    ('67901b7c-2ac1-5a9d-a7c7-339fce254f00'::uuid, 'emc', '5e', 'Voter : le droit de vote et les élections', 'Pour combien de temps les députés sont-ils élus ?', 'mcq', '["6 ans","7 ans","5 ans","4 ans"]'::jsonb, 2, 'Les députés, comme le président de la République et les députés européens, sont élus pour 5 ans ; les conseillers municipaux pour 6 ans.', 2),
