    ('dc4f34fe-95a7-5dbc-8347-b14b76f1579f'::uuid, 'emc', '5e', 'L’engagement et la solidarité', 'Quelle forme d’engagement consiste à défendre des droits collectifs au travail ?', 'mcq', '["L’engagement associatif","L’engagement scolaire","L’engagement syndical","Le service civique"]'::jsonb, 2, 'Le syndicat défend les droits collectifs des salariés.', 2),
