    ('be912272-7840-5724-b406-8eedb2c94b6c'::uuid, 'emc', '5e', 'Le respect de la vie privée et l’identité numérique', 'Comment s’appelle le droit de demander qu’on supprime ses données ?', 'mcq', '["Le droit à l’effacement, ou « droit à l’oubli »","Le droit d’accès","Le droit de rectification","Le droit de réponse"]'::jsonb, 0, 'Le RGPD prévoit l’accès, la rectification, l’opposition et l’effacement, dit « droit à l’oubli ».', 3),
    ('d3ebeb87-e363-5def-9956-4eded774ee52'::uuid, 'emc', '5e', 'Le respect de la vie privée et l’identité numérique', 'Avant 15 ans en France, que faut-il pour qu’un service traite ses données ?', 'mcq', '["Rien de particulier","Une carte d’identité","L’accord de la CNIL","L’accord d’un parent"]'::jsonb, 3, 'L’âge du consentement autonome est fixé à 15 ans ; en dessous, l’accord d’un parent est nécessaire.', 4),
    ('b26d1b85-44d0-503c-83f6-215ac1baa522'::uuid, 'emc', '4e', 'L’engagement et la solidarité', 'Combien de temps dure une mission de service civique ?', 'mcq', '["Deux semaines","De 6 à 12 mois","Trois ans","Toute la scolarité"]'::jsonb, 1, 'Le service civique est une mission d’intérêt général indemnisée, de 6 à 12 mois, accessible dès 16 ans.', 1),
    ('2ffb0177-994d-5928-82c2-79e2cec7caad'::uuid, 'emc', '4e', 'L’engagement et la solidarité', 'Quelle forme d’engagement consiste à défendre des droits collectifs au travail ?', 'mcq', '["L’engagement associatif","L’engagement scolaire","L’engagement syndical","Le service civique"]'::jsonb, 2, 'Le syndicat défend les droits collectifs des salariés.', 2),
    ('8a04b4f1-c9b6-5882-a336-5a1747f00340'::uuid, 'emc', '4e', 'L’engagement et la solidarité', 'Qu’est-ce qui finance la solidarité organisée ?', 'mcq', '["Les cotisations et l’impôt","Les dons des plus riches","La charité des associations","Les entreprises seules"]'::jsonb, 0, 'Ce n’est pas de la charité mais un droit, financé par les cotisations et l’impôt.', 3),
    ('74f30a56-b770-50c4-9c7b-e0aab3c35bf4'::uuid, 'emc', '4e', 'L’engagement et la solidarité', 'Lequel de ces gestes relève de la solidarité de proximité ?', 'mcq', '["Payer ses cotisations","Voter aux élections","Toucher une pension de retraite","Donner son sang"]'::jsonb, 3, 'Don du sang, maraudes, aide aux devoirs : la solidarité de proximité complète le système public là où il n’atteint pas.', 4),
    ('77cf56ef-d3d1-50f0-b001-f65fe7850bed'::uuid, 'emc', '4e', 'La justice en France', 'Quel tribunal juge une contravention, comme un excès de vitesse ?', 'mcq', '["Le tribunal correctionnel","Le tribunal de police","La cour d’assises","Le tribunal administratif"]'::jsonb, 1, 'Contravention → tribunal de police ; délit → tribunal correctionnel ; crime → cour d’assises ou cour criminelle.', 1),
    ('ab6abdbf-c6c9-506e-a30f-f44bdc7a7f0e'::uuid, 'emc', '4e', 'La justice en France', 'Un citoyen conteste une décision de sa mairie. Quel ordre de juridiction est compétent ?', 'mcq', '["L’ordre judiciaire","La cour d’assises","L’ordre administratif","Le juge des enfants"]'::jsonb, 2, 'Les litiges entre les citoyens et l’administration relèvent de l’ordre administratif (tribunal administratif, Conseil d’État).', 2),
    ('5a1392dd-33dc-50f1-b297-b424e66ec3e6'::uuid, 'emc', '4e', 'La justice en France', 'Que permet l’aide juridictionnelle ?', 'mcq', '["D’accéder à la justice quand on a peu de moyens","De faire appel deux fois","D’éviter un procès","De choisir son juge"]'::jsonb, 0, 'L’aide juridictionnelle prend en charge les frais de justice des plus modestes : la justice doit être accessible à tous.', 3),
    ('4cad7470-70bf-54be-bc1e-3765d943640f'::uuid, 'emc', '4e', 'La justice en France', 'Quel acteur du procès consigne ce qui se dit à l’audience ?', 'mcq', '["Le procureur","L’avocat","Le juré","Le greffier"]'::jsonb, 3, 'Le greffier consigne les débats et les décisions ; le juge tranche, le procureur poursuit, l’avocat défend.', 4),
    ('d57ccdc9-68bc-5ac2-8f19-63b3415206a3'::uuid, 'emc', '5e', 'La citoyenneté française et européenne', 'Comment devient-on français par filiation ?', 'mcq', '["En naissant en France","En ayant au moins un parent français","En vivant cinq ans en France","En se mariant"]'::jsonb, 1, 'La filiation donne la nationalité française à l’enfant dont au moins un parent est français, où qu’il naisse.', 1),
    ('b7beb964-fe42-5f92-9f0b-4c1856fa42ac'::uuid, 'emc', '5e', 'La citoyenneté française et européenne', 'Hors d’Europe, un citoyen européen peut demander la protection…', 'mcq', '["de l’ONU uniquement","de son seul pays d’origine","du consulat de n’importe quel État membre","du Parlement européen"]'::jsonb, 2, 'La citoyenneté européenne donne droit à la protection consulaire de n’importe quel État membre présent sur place.', 2),
    ('847a6421-04dc-54d3-be0d-d4cc5ce35c05'::uuid, 'emc', '5e', 'La citoyenneté française et européenne', 'Adhérer à un parti politique est un droit…', 'mcq', '["politique","civil","social","européen uniquement"]'::jsonb, 0, 'Voter, être élu, adhérer à un parti sont des droits politiques ; l’expression ou la circulation sont des droits civils.', 3),
    ('23051c3c-05c4-5983-a779-a0339f24b029'::uuid, 'emc', '5e', 'La citoyenneté française et européenne', 'Devant quelle institution un citoyen européen peut-il déposer une pétition ?', 'mcq', '["Le Conseil constitutionnel","L’Assemblée nationale","La CNIL","Le Parlement européen"]'::jsonb, 3, 'Le droit de pétition devant le Parlement européen fait partie des droits de la citoyenneté européenne.', 4),
