    ('d15fc548-a55e-5152-b872-2bb9a8b99ee6'::uuid, 'espagnol', '5e', 'Les adjectifs', 'Où se place un adjectif de couleur ?', 'mcq', '["Toujours avant le nom","Toujours après le nom","Avant ou après, sans changement","Seulement après un verbe"]'::jsonb, 1, 'Couleur, forme, nationalité et religion classent objectivement : l’adjectif reste après le nom (un coche rojo).', 1),
    ('5c17a16e-f973-56fb-8ca4-dbd505a03faf'::uuid, 'espagnol', '5e', 'Les adjectifs', 'Que signifie « libros diferentes » ?', 'mcq', '["Plusieurs livres","Des livres récents","Des livres dissemblables","Quelques livres"]'::jsonb, 2, 'Après le nom, diferentes veut dire « qui ne se ressemblent pas » ; devant (diferentes libros), il signifie « plusieurs ».', 2),
    ('03b4d6b8-aff0-5cac-b726-b0f5b5b9cb59'::uuid, 'espagnol', '5e', 'Les adjectifs', 'Quel est le féminin de « trabajador » ?', 'mcq', '["trabajador","trabajadriz","trabajadoresa","trabajadora"]'::jsonb, 3, 'Les adjectifs en -or forment un féminin en ajoutant -a : trabajador, trabajadora.', 3),
    ('7866fb03-93d9-5d7e-8ca4-203c1d0f7afe'::uuid, 'espagnol', '5e', 'Les adjectifs', 'Que signifie « un hecho cierto » ?', 'mcq', '["Un fait avéré","Un certain fait","Un fait ancien","Un fait discutable"]'::jsonb, 0, 'Après le nom, cierto veut dire « vrai, avéré » ; devant (un cierto encanto), il signifie « un certain ».', 4),
    ('54186a28-e2bd-562b-8edd-f8382e4d7e3c'::uuid, 'espagnol', '5e', 'Le passé composé', '¿Ya ___ comido, chicos?', 'mcq', '["habéis","hemos","habés","ha"]'::jsonb, 0, 'Haber au présent fait habéis à vosotros : ¿Ya habéis comido?', 1),
