    ('f1be9e67-4aee-50f2-a744-cf10b6b51894'::uuid, 'espagnol', '5e', 'Le passé composé', 'Quel emploi illustre « Me he roto la pierna » (et je porte encore le plâtre) ?', 'mcq', '["Une habitude passée","Un récit historique","Un fait dont les effets durent","Une supposition"]'::jsonb, 2, 'Le pretérito perfecto rattache au présent un fait dont les effets se font encore sentir.', 3),
    ('de73c595-b60d-5ec2-867d-a480e886594a'::uuid, 'espagnol', '5e', 'Le passé composé', 'Que fait le passé simple par rapport au passé composé ?', 'mcq', '["Il raccroche le fait au présent","Il décrit un décor","Il exprime une habitude","Il coupe le fait du présent"]'::jsonb, 3, 'Le passé simple coupe le fait du présent ; le passé composé l’y raccroche.', 4),
    ('f85a424d-7a18-5215-8f24-348363feb9bf'::uuid, 'espagnol', '4e', 'La comparaison', 'Tengo menos dinero ___ tú.', 'mcq', '["que","de","como","cual"]'::jsonb, 0, 'Le comparatif d’infériorité se construit avec menos… que : menos dinero que tú.', 1),
