    ('8c9841be-569e-5756-837b-673def1ce057'::uuid, 'espagnol', '4e', 'Les indéfinis', 'No hay ___ problema.', 'mcq', '["ningún","ninguno","ninguna","ningunos"]'::jsonb, 0, 'Devant un nom masculin singulier, ninguno s’apocope en ningún ; il s’emploie presque toujours au singulier.', 1),
