    ('74e3ba0b-f736-53c9-b9bf-2dbd99d0fbb6'::uuid, 'sport', '4e', 'La sécurité et les premiers secours', 'Quelle est la règle de sécurité non négociable en escalade ?', 'mcq', '["La parade","L’assurage","La zone de lancer dégagée","Le contact interdit"]'::jsonb, 1, 'En escalade, on est toujours assuré ; la parade est la règle de la gymnastique.', 1),
    ('9875ba3b-5a38-5e9d-982e-7b826a0e32c4'::uuid, 'sport', '4e', 'La sécurité et les premiers secours', 'Combien de temps applique-t-on la glace sur une entorse, et comment ?', 'mcq', '["1 heure, directement sur la peau","2 minutes, directement sur la peau","15 à 20 minutes, jamais à même la peau","Toute la nuit, sous un bandage serré"]'::jsonb, 2, 'Dans le protocole RICE, la glace s’applique 15 à 20 minutes, protégée par un tissu pour ne pas brûler la peau.', 2),
    ('8189490f-9f6f-5c40-8ced-bba42940cca4'::uuid, 'sport', '4e', 'La sécurité et les premiers secours', 'Quel numéro d’urgence permet d’alerter par SMS ?', 'mcq', '["Le 114","Le 15","Le 18","Le 112"]'::jsonb, 0, 'Le 114 reçoit les alertes par SMS, notamment pour les personnes sourdes ou malentendantes.', 3),
    ('3867f3de-ad65-5167-b6dc-cb5a352d5fad'::uuid, 'sport', '4e', 'La sécurité et les premiers secours', 'Pâleur, sueurs et vertiges sont les signes…', 'mcq', '["d’une entorse","d’un claquage","d’une fracture","d’un malaise"]'::jsonb, 3, 'Le malaise se reconnaît à la pâleur, aux sueurs et aux vertiges ; on arrête l’effort et on prévient l’adulte.', 4),
