    ('f8cb6525-4598-5fe2-8616-3fc98f88b486'::uuid, 'sport', '4e', 'Les rôles sociaux : arbitre, observateur, coach', 'De quoi l’observateur a-t-il besoin pour faire un relevé utile ?', 'mcq', '["D’un sifflet","D’un critère mesurable","D’être le meilleur joueur","D’un avis personnel"]'::jsonb, 1, 'L’observateur relève des données précises selon un critère : « 7 passes sur 10 réussies » se travaille, « il a bien joué » non.', 1),
    ('3c7aff77-5f11-5f94-b990-5bc39775674b'::uuid, 'sport', '4e', 'Les rôles sociaux : arbitre, observateur, coach', 'Que se passe-t-il, selon le cours, quand un arbitre hésite ?', 'mcq', '["Il gagne la confiance des joueurs","Le match devient plus juste","Il perd le match","Rien de particulier"]'::jsonb, 2, 'L’arbitre doit décider vite et assumer : un arbitre qui hésite perd le contrôle du match.', 2),
    ('166168a1-bdde-5786-a0cf-3d506df36268'::uuid, 'sport', '4e', 'Les rôles sociaux : arbitre, observateur, coach', 'Face à une décision d’arbitrage qu’on juge injuste, que peut-on faire ?', 'mcq', '["Demander une explication, sans insulter","Quitter le terrain","Contester à chaque action","Arbitrer soi-même"]'::jsonb, 0, 'On peut demander une explication ; contester systématiquement ou insulter rend le rôle intenable.', 3),
