    ('1ea84352-cb9a-5ee7-8c04-827c4e826693'::uuid, 'svt', '5e', 'La puberté et le fonctionnement des appareils génitaux', 'Lequel de ces changements est un caractère sexuel secondaire ?', 'mcq', '["Le fonctionnement des ovaires","La production de spermatozoïdes","La mue de la voix","La formation des gamètes"]'::jsonb, 2, 'Pilosité, seins, mue de la voix ou poussée de croissance sont secondaires ; le fonctionnement des organes génitaux est primaire.', 3),
    ('725fca0f-0ba3-5751-8247-098bc7f8eb4c'::uuid, 'svt', '5e', 'La puberté et le fonctionnement des appareils génitaux', 'Quand le stock d’ovocytes d’une femme est-il constitué ?', 'mcq', '["À la puberté","À chaque cycle","À la ménopause","Dès la naissance"]'::jsonb, 3, 'Le stock est constitué dès la naissance, alors que les spermatozoïdes sont fabriqués en permanence.', 4),
