    ('98d390aa-e4cd-5394-b9a0-c2d2828ab2a9'::uuid, 'svt', '5e', 'Volcanisme et risques associés', 'Quel volcan est connu pour ses éruptions explosives ?', 'mcq', '["Le Piton de la Fournaise","Un volcan d’Hawaï","Un volcan d’Islande","La Montagne Pelée"]'::jsonb, 3, 'La Montagne Pelée, comme le Vésuve ou le Merapi, a un magma visqueux ; les trois autres sont effusifs.', 1),
    ('7b60dfb4-978f-59ba-9efe-b20d1564d6e9'::uuid, 'svt', '5e', 'Volcanisme et risques associés', 'Quel magma donne une éruption effusive ?', 'mcq', '["Un magma visqueux, riche en silice","Un magma fluide, pauvre en silice","Un magma solide","Un magma sans gaz ni lave"]'::jsonb, 1, 'Dans un magma fluide, les gaz s’échappent facilement : la lave coule au lieu d’exploser.', 2),
    ('ddeee745-e8d7-5875-9143-b28d5019294a'::uuid, 'svt', '5e', 'Volcanisme et risques associés', 'Qu’est-ce qu’un lahar ?', 'mcq', '["Une nuée ardente","Un gaz toxique","Une coulée de boue","Une coulée de lave"]'::jsonb, 2, 'Les lahars sont des coulées de boue volcanique, un des risques associés aux volcans.', 3),
    ('2e3ee1ce-ef1a-5368-ac6e-0a0f07541bea'::uuid, 'svt', '5e', 'Volcanisme et risques associés', 'Quelle éruption de 1991 a été anticipée, sauvant des dizaines de milliers de vies ?', 'mcq', '["Celle du Pinatubo","Celle du Vésuve","Celle de la Montagne Pelée","Celle du Merapi"]'::jsonb, 0, 'La surveillance de l’observatoire et l’évacuation préparée ont permis de sauver la population.', 4),
