    ('76c403ff-3324-5c11-aace-c746dc22c086'::uuid, 'svt', '4e', 'La puberté et le fonctionnement des appareils génitaux', 'Comment appelle-t-on l’arrêt du fonctionnement cyclique des ovaires ?', 'mcq', '["La ménopause","La puberté","L’ovulation","La nidation"]'::jsonb, 0, 'Chez l’homme, la production de spermatozoïdes n’a pas d’arrêt net.', 1),
    ('cafe9301-6b6f-51ef-b5f9-b4ca1f2f2bd9'::uuid, 'svt', '4e', 'La puberté et le fonctionnement des appareils génitaux', 'Quelle hormone les testicules produisent-ils ?', 'mcq', '["Les œstrogènes","La testostérone","L’insuline","La progestérone"]'::jsonb, 1, 'Les testicules produisent la testostérone ; les ovaires, les œstrogènes et la progestérone.', 2),
    ('66b472e3-081d-52c9-b766-b0a23dc47b79'::uuid, 'svt', '4e', 'La puberté et le fonctionnement des appareils génitaux', 'Lequel de ces changements est un caractère sexuel secondaire ?', 'mcq', '["Le fonctionnement des ovaires","La production de spermatozoïdes","La mue de la voix","La formation des gamètes"]'::jsonb, 2, 'Pilosité, seins, mue de la voix ou poussée de croissance sont secondaires ; le fonctionnement des organes génitaux est primaire.', 3),
    ('5fd9df76-1e29-5270-ad5d-577344881191'::uuid, 'svt', '4e', 'La puberté et le fonctionnement des appareils génitaux', 'Quand le stock d’ovocytes d’une femme est-il constitué ?', 'mcq', '["À la puberté","À chaque cycle","À la ménopause","Dès la naissance"]'::jsonb, 3, 'Le stock est constitué dès la naissance, alors que les spermatozoïdes sont fabriqués en permanence.', 4),
    ('09c16cee-4ae8-5201-ba22-43db8d6f1045'::uuid, 'svt', '4e', 'Nutrition et organisation des plantes', 'Quel rôle les plantes chlorophylliennes jouent-elles dans les réseaux trophiques ?', 'mcq', '["Producteurs primaires","Décomposeurs","Consommateurs secondaires","Prédateurs"]'::jsonb, 0, 'Elles fabriquent la matière organique dont dépendent tous les autres maillons.', 1),
    ('785a2715-f3b7-5637-a827-58f578999317'::uuid, 'svt', '4e', 'Nutrition et organisation des plantes', 'Quel vaisseau transporte la sève élaborée ?', 'mcq', '["Le xylème","Le phloème","Le poil absorbant","Le stomate"]'::jsonb, 1, 'Le phloème distribue la sève élaborée, riche en sucres ; le xylème conduit la sève brute.', 2),
    ('9c3665fb-c60e-5a03-8737-4845c927c79a'::uuid, 'svt', '4e', 'Nutrition et organisation des plantes', 'Quelles structures des racines multiplient la surface d’absorption ?', 'mcq', '["Les stomates","Les chloroplastes","Les poils absorbants","Les feuilles caduques"]'::jsonb, 2, 'Les poils absorbants prélèvent l’eau et les sels minéraux sur une très grande surface.', 3),
    ('d689c024-37fe-5303-bf71-299e2baea409'::uuid, 'svt', '4e', 'Nutrition et organisation des plantes', 'Qu’est-ce qui fait monter la sève brute des racines vers les feuilles ?', 'mcq', '["La photosynthèse des racines","La gravité","La respiration nocturne","La transpiration par les stomates"]'::jsonb, 3, 'L’eau qui s’évapore par les stomates tire la colonne de sève brute vers le haut.', 4),
    ('3a7207ca-5f16-5a18-a0ec-61983d6db9f0'::uuid, 'svt', '5e', 'Nutrition et organisation des plantes', 'Quel rôle les plantes chlorophylliennes jouent-elles dans les réseaux trophiques ?', 'mcq', '["Producteurs primaires","Décomposeurs","Consommateurs secondaires","Prédateurs"]'::jsonb, 0, 'Elles fabriquent la matière organique dont dépendent tous les autres maillons.', 1),
