    ('2b2914ec-7b86-5ebb-a4be-87cab07c1b59'::uuid, 'svt', '5e', 'Nutrition et organisation des plantes', 'Quelles structures des racines multiplient la surface d’absorption ?', 'mcq', '["Les stomates","Les chloroplastes","Les poils absorbants","Les feuilles caduques"]'::jsonb, 2, 'Les poils absorbants prélèvent l’eau et les sels minéraux sur une très grande surface.', 3),
    ('c5447ae4-a89a-5301-9239-b77bb7fab159'::uuid, 'svt', '5e', 'Nutrition et organisation des plantes', 'Qu’est-ce qui fait monter la sève brute des racines vers les feuilles ?', 'mcq', '["La photosynthèse des racines","La gravité","La respiration nocturne","La transpiration par les stomates"]'::jsonb, 3, 'L’eau qui s’évapore par les stomates tire la colonne de sève brute vers le haut.', 4),
    ('1e9e5c04-56e2-5cd1-a66d-c784ee79c768'::uuid, 'svt', '5e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Quelle mesure aide les poissons migrateurs à se reproduire malgré les barrages ?', 'mcq', '["Les passes à poissons","La pêche des adultes reproducteurs","L’éclairage des rivières la nuit","L’introduction d’espèces concurrentes"]'::jsonb, 0, 'Les passes à poissons rétablissent l’accès aux sites de reproduction, comme les corridors pour les espèces terrestres.', 1),
    ('77178109-b1db-5076-a074-a08896724128'::uuid, 'svt', '5e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Lequel de ces animaux pratique la fécondation externe ?', 'mcq', '["Le chat","L’oursin","Le pigeon","Le lézard"]'::jsonb, 1, 'Chez l’oursin, comme chez les poissons et les amphibiens, la fécondation a lieu dans l’eau.', 2),
    ('458706bd-0bee-5ce8-810a-189fd69cffaf'::uuid, 'svt', '5e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Comment certains polluants dérèglent-ils la fertilité ?', 'mcq', '["En modifiant la durée du jour","En augmentant la température de l’eau","En agissant comme perturbateurs endocriniens","En attirant des prédateurs"]'::jsonb, 2, 'Les perturbateurs endocriniens interfèrent avec les hormones qui contrôlent la reproduction.', 3),
    ('3ed25bc8-c546-5ce8-9393-fac644860cc0'::uuid, 'svt', '5e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Quels facteurs font diminuer l’effectif d’une population ?', 'mcq', '["La natalité et l’immigration","La natalité et la mortalité","L’immigration et l’émigration","La mortalité et l’émigration"]'::jsonb, 3, 'Les morts et les départs réduisent l’effectif ; les naissances et les arrivées l’augmentent.', 4),
    ('c8e40886-1ae1-58e8-a789-ac9de2b567a3'::uuid, 'svt', '5e', 'La transmission du patrimoine génétique', 'À quoi sert la mitose dans l’organisme ?', 'mcq', '["À la croissance, au renouvellement et à la réparation des tissus","À produire les gamètes","À la fécondation","À réduire le nombre de chromosomes"]'::jsonb, 0, 'La mitose donne deux cellules identiques à 46 chromosomes ; la méiose produit les gamètes.', 1),
    ('8e2dd6be-ee26-55ad-859c-dbef9ce7c09a'::uuid, 'svt', '5e', 'La transmission du patrimoine génétique', 'Quelle est la 23e paire de chromosomes d’un homme ?', 'mcq', '["XX","XY","YY","Un seul X"]'::jsonb, 1, 'Chez la femme, la 23e paire est XX ; chez l’homme, XY.', 2),
    ('4a4a134f-23d2-559b-9e90-03d7d3b1cf03'::uuid, 'svt', '5e', 'La transmission du patrimoine génétique', 'Sans méiose, combien de chromosomes aurait la cellule œuf humaine ?', 'mcq', '["23","46","92","69"]'::jsonb, 2, 'Deux gamètes à 46 chromosomes donneraient 92 : la méiose, en les réduisant à 23, garde le nombre constant.', 3),
    ('5590a778-fcf0-56e8-aa61-d0f1ec394365'::uuid, 'svt', '5e', 'La transmission du patrimoine génétique', 'Comment appelle-t-on la photographie ordonnée des chromosomes d’une cellule ?', 'mcq', '["L’ADN","Le génotype","L’allèle","Le caryotype"]'::jsonb, 3, 'Le caryotype permet de repérer un chromosome en trop ou en moins, comme dans la trisomie 21.', 4),
    ('a683fe9e-6e43-5512-ad95-0f5f031fc7ab'::uuid, 'svt', '5e', 'De la fécondation à la naissance', 'Pourquoi le placenta n’est-il pas un filtre absolu ?', 'mcq', '["Parce que l’alcool, le tabac, les drogues et certains virus le traversent","Parce qu’il laisse passer le sang maternel","Parce qu’il bloque le dioxygène","Parce qu’il disparaît au sixième mois"]'::jsonb, 0, 'C’est pourquoi aucun alcool, ni tabac, ni drogue n’est sans risque pendant la grossesse.', 1),
    ('e770decd-25b5-5fb7-ad89-24addf0e3d86'::uuid, 'svt', '5e', 'De la fécondation à la naissance', 'Qu’est-ce qui détermine le sexe de l’enfant ?', 'mcq', '["Le chromosome apporté par l’ovule","Le chromosome apporté par le spermatozoïde","La température de la mère","L’alimentation pendant la grossesse"]'::jsonb, 1, 'L’ovule apporte toujours un X ; le spermatozoïde apporte un X ou un Y.', 2),
    ('4e3303a4-9d60-5d5d-b3b5-808163497e94'::uuid, 'svt', '5e', 'De la fécondation à la naissance', 'Quelle taille mesure l’embryon à 8 semaines ?', 'mcq', '["Environ 50 cm","Environ 15 cm","Environ 3 cm","Environ 3 mm"]'::jsonb, 2, 'À 8 semaines, tous les organes sont en place ; le bébé mesure environ 50 cm à terme.', 3),
    ('a50e2a6a-ad41-5390-8b0f-31cacc3e3a6a'::uuid, 'svt', '5e', 'De la fécondation à la naissance', 'Qu’appelle-t-on la délivrance ?', 'mcq', '["La naissance du bébé","La coupure du cordon","La première respiration","L’expulsion du placenta après la naissance"]'::jsonb, 3, 'Contractions, expulsion du bébé, coupure du cordon, puis délivrance du placenta.', 4),
    ('92f7d427-c3d5-5661-b6bd-585f6e76bf1a'::uuid, 'svt', '5e', 'L’effort physique', 'À quoi sert l’échauffement ?', 'mcq', '["À préparer progressivement le cœur, les muscles et les articulations","À épuiser les réserves avant l’effort","À se déshydrater","À augmenter la fréquence cardiaque de repos"]'::jsonb, 0, 'Il met le corps en route peu à peu et limite les blessures.', 1),
    ('6a221fe9-a6e9-579a-b61a-704d142bf436'::uuid, 'svt', '5e', 'L’effort physique', 'Par combien le débit cardiaque peut-il être multiplié à l’effort ?', 'mcq', '["Par 2","Par 5","Par 50","Il ne change pas"]'::jsonb, 1, 'Le cœur bat plus vite et plus fort : le débit est multiplié par 5.', 2),
    ('840670c5-60b4-54f7-b357-5c80165f4007'::uuid, 'svt', '5e', 'L’effort physique', 'Dans quelle réserve le muscle puise-t-il pour les efforts longs ?', 'mcq', '["Le calcium des os","Les protéines du cœur","Les lipides","L’eau"]'::jsonb, 2, 'Après le glycogène du muscle et le glucose du sang, les lipides prennent le relais.', 3),
    ('98c2ed3f-65b5-5099-b01b-30b8abe57979'::uuid, 'svt', '5e', 'L’effort physique', 'Que produit la fermentation lactique ?', 'mcq', '["De l’urée","Du glycogène","Du dioxygène","De l’acide lactique"]'::jsonb, 3, 'Quand le dioxygène manque, cette voie fournit peu d’énergie et produit de l’acide lactique.', 4),
    ('40b32e86-b76e-5b60-9664-b664f9d1d190'::uuid, 'svt', '5e', 'Les séismes : causes et risques associés', 'Où les dégâts d’un séisme sont-ils en général les plus importants ?', 'mcq', '["Au foyer, en profondeur","Le plus loin possible de la faille","À l’épicentre","Au centre de la Terre"]'::jsonb, 2, 'L’épicentre est le point de la surface situé à la verticale du foyer.', 1),
    ('cee71084-c40e-52b7-9b48-b65461222cb7'::uuid, 'svt', '5e', 'Les séismes : causes et risques associés', 'Sur quel élément du risque sismique peut-on agir ?', 'mcq', '["L’aléa","La vulnérabilité","La magnitude","Le mouvement des plaques"]'::jsonb, 1, 'On ne peut pas empêcher un séisme, mais on peut réduire l’exposition des personnes et des bâtiments.', 2),
    ('07b845ed-82fa-52c1-8254-9ed6b8aacbe6'::uuid, 'svt', '5e', 'Les séismes : causes et risques associés', 'Combien de valeurs d’intensité un même séisme possède-t-il ?', 'mcq', '["Une seule pour tout le séisme","Deux","Aucune","Une par lieu où il est ressenti"]'::jsonb, 3, 'L’intensité décrit les effets en un lieu ; la magnitude, elle, est unique pour un séisme.', 3),
    ('9332148e-bd77-520a-9c14-0c02fd9470b5'::uuid, 'svt', '5e', 'Les séismes : causes et risques associés', 'Quelle région française présente une sismicité forte, avec des normes parasismiques obligatoires ?', 'mcq', '["Les Antilles","La Bretagne","Le Bassin parisien","Les Landes"]'::jsonb, 0, 'Les Antilles sont en zone de subduction ; les Alpes, les Pyrénées ou l’Alsace ont une sismicité modérée.', 4),
    ('42ef7d16-a6e2-56e8-9cec-71b6989dff4d'::uuid, 'svt', '4e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Que permet de fabriquer, plus exactement, l’information portée par un gène ?', 'mcq', '["Une protéine","Un chromosome","Une cellule","Un sucre"]'::jsonb, 0, 'Un gène est un segment d’ADN qui porte l’information de fabrication d’une protéine.', 1),
    ('e972cd37-7d91-5345-8a40-4048d200942f'::uuid, 'svt', '4e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Qui a décrit la structure de l’ADN en 1953 ?', 'mcq', '["Darwin et Wallace","Watson, Crick, Franklin et Wilkins","Mendel","Pasteur et Koch"]'::jsonb, 1, 'Ils ont établi que l’ADN est une double hélice de deux brins complémentaires.', 2),
    ('7bdad8d9-0d77-5acb-b785-838d9c578b28'::uuid, 'svt', '4e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Lequel de ces caractères est un caractère individuel ?', 'mcq', '["Avoir deux yeux","Avoir une colonne vertébrale","Le groupe sanguin","Avoir cinq doigts"]'::jsonb, 2, 'Le groupe sanguin varie d’une personne à l’autre ; les trois autres sont des caractères d’espèce.', 3),
    ('81e4add3-9ffa-57b7-bc0f-bded58efe5f4'::uuid, 'svt', '4e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Combien de bases différentes composent l’ADN ?', 'mcq', '["Deux","Vingt","Quarante-six","Quatre"]'::jsonb, 3, 'A, T, G et C : un alphabet de quatre lettres, universel dans tout le vivant.', 4),
    ('910041bf-5d04-5e40-9c62-c683c739b2fe'::uuid, 'svt', '4e', 'Sport et santé', 'Pourquoi les régimes restrictifs sont-ils dangereux à l’adolescence ?', 'mcq', '["Parce qu’ils compromettent la croissance","Parce qu’ils font grandir trop vite","Parce qu’ils améliorent trop les performances","Parce qu’ils remplacent le sport"]'::jsonb, 0, 'L’adolescent en croissance a des besoins élevés : aucun complément ne remplace une alimentation variée.', 1),
    ('54f43f0d-ea86-511d-9764-7b3c52f4e05f'::uuid, 'svt', '4e', 'Sport et santé', 'Quel apport sert surtout à la réparation des muscles ?', 'mcq', '["Les glucides complexes","Les protéines","Les fibres","L’eau"]'::jsonb, 1, 'Les protéines réparent les muscles ; les glucides complexes soutiennent l’endurance.', 2),
    ('99bceebf-58b0-5f4a-b107-c69d8b50c05d'::uuid, 'svt', '4e', 'Sport et santé', 'Quel diabète l’activité physique aide-t-elle à prévenir ?', 'mcq', '["Le diabète de type 1","Aucun diabète","Le diabète de type 2","Tous les diabètes sans exception"]'::jsonb, 2, 'En augmentant la dépense énergétique, l’activité aide à contrôler le poids et prévient le diabète de type 2.', 3),
    ('cad3a9ae-3e83-5190-807b-cb7c52f2d25a'::uuid, 'svt', '4e', 'Sport et santé', 'Quels bénéfices sociaux l’activité physique apporte-t-elle ?', 'mcq', '["Une meilleure vue","Une taille plus grande","Une peau plus claire","L’appartenance à un groupe, des règles partagées, la coopération"]'::jsonb, 3, 'La santé selon l’OMS est aussi sociale : le sport crée des liens.', 4),
    ('503540e7-0e87-5389-b909-30a0d740b3db'::uuid, 'svt', '4e', 'La reproduction asexuée', 'Quel animal peut reconstituer un individu entier à partir d’un fragment ?', 'mcq', '["L’étoile de mer","Le puceron","La levure","Le lézard"]'::jsonb, 0, 'C’est la fragmentation suivie de régénération, observée aussi chez la planaire.', 1),
    ('c916b7ee-d86f-50ea-b52c-038f867ed098'::uuid, 'svt', '4e', 'La reproduction asexuée', 'Comment la pomme de terre se multiplie-t-elle de façon asexuée ?', 'mcq', '["Par stolons","Par tubercules","Par bulbes","Par drageons"]'::jsonb, 1, 'Chaque tubercule peut donner une nouvelle plante, clone de la plante mère.', 2),
    ('69fdc636-be35-5f05-8aae-1c5ba16b8ecf'::uuid, 'svt', '4e', 'La reproduction asexuée', 'Quel mode de reproduction asexuée pratiquent les bactéries ?', 'mcq', '["Le bourgeonnement","La parthénogenèse","La scissiparité","Le bouturage"]'::jsonb, 2, 'La bactérie se divise en deux individus identiques : c’est la scissiparité.', 3),
    ('027abdcd-575a-50b5-850a-36f02f281269'::uuid, 'svt', '4e', 'La reproduction asexuée', 'Quel épisode historique montre le danger d’une culture faite de clones ?', 'mcq', '["La peste noire","L’éruption du Vésuve","La disparition des dinosaures","La grande famine irlandaise de la pomme de terre"]'::jsonb, 3, 'Toutes les plantes, identiques, ont réagi de la même façon à la maladie : la récolte entière a été détruite.', 4),
    ('a4365008-48d0-50d6-b245-39b5c5493a53'::uuid, 'technologie', '4e', 'La fonction technique et le principe technique', 'Sur quel principe technique reposent tous les freins de vélo ?', 'mcq', '["La gravité","Le magnétisme","Le frottement","La dilatation"]'::jsonb, 2, 'Patins, disque ou rétropédalage : ces solutions différentes exploitent toutes le frottement.', 1),
    ('26602a21-74c0-59c7-846c-1180ccdc7c67'::uuid, 'technologie', '4e', 'La fonction technique et le principe technique', 'Comment exprime-t-on une fonction d’usage ?', 'mcq', '["Par un verbe à l’infinitif","Par un nombre","Par le nom d’un composant","Par une unité de mesure"]'::jsonb, 0, 'On écrit le service rendu par un verbe à l’infinitif : « se déplacer », « éclairer ».', 2),
    ('0a52bcf4-72cb-5ed6-823e-a38e11e6267a'::uuid, 'technologie', '4e', 'La fonction technique et le principe technique', 'Pour un vélo, lequel de ces éléments est une solution technique ?', 'mcq', '["Freiner","Le frottement","Se déplacer","Un frein à disque"]'::jsonb, 3, 'Le frein à disque est le composant concret retenu ; freiner est une fonction technique, le frottement un principe, se déplacer la fonction d’usage.', 3),
    ('8d1ea3ac-2f56-51e3-9d86-2e8ea24c6845'::uuid, 'technologie', '4e', 'La fonction technique et le principe technique', 'Dans l’exigence « distance de freinage : moins de 5 m à 20 km/h », que désigne « moins de 5 m » ?', 'mcq', '["Le critère","Le niveau","La fonction d’usage","Le principe technique"]'::jsonb, 1, 'Le critère est ce qu’on mesure (la distance de freinage) ; le niveau est la valeur à atteindre.', 4),
    ('c8a4fbe6-909c-5d75-8bf8-5e45dceba48f'::uuid, 'technologie', '5e', 'Programmation graphique et programmation textuelle', 'Quelle programmation convient le mieux aux programmes longs ?', 'mcq', '["La programmation graphique","La programmation textuelle","Aucune des deux","Les deux aussi bien"]'::jsonb, 1, 'Les blocs deviennent vite illisibles sur un long programme ; le texte n’a pas de limite de taille.', 1),
    ('c95e05c4-e261-5e0d-9f5c-ca23d08c2d34'::uuid, 'technologie', '5e', 'Programmation graphique et programmation textuelle', 'Quel langage textuel sert souvent à programmer une carte Arduino ?', 'mcq', '["Scratch","Blockly","Le C ou le C++","Snap!"]'::jsonb, 2, 'Scratch, Blockly et Snap! sont des environnements par blocs ; l’Arduino se programme le plus souvent en C ou C++.', 2),
    ('365b9388-a8fe-5e80-9279-0fa8596898cc'::uuid, 'technologie', '5e', 'Programmation graphique et programmation textuelle', 'En programmation par blocs, que se passe-t-il si deux blocs sont incompatibles ?', 'mcq', '["Le programme plante à l’exécution","Un message d’erreur de syntaxe s’affiche","Ils se transforment en texte","Ils ne s’emboîtent pas"]'::jsonb, 3, 'C’est pour cela qu’aucune faute de syntaxe n’est possible avec les blocs.', 3),
    ('27ea9523-161a-5c4d-988b-00322cdd5257'::uuid, 'technologie', '5e', 'Programmation graphique et programmation textuelle', 'Que demande le programme du cycle 4 à propos des deux façons de programmer ?', 'mcq', '["Savoir lire et modifier les deux","Maîtriser seulement les blocs","Maîtriser seulement Python","Savoir écrire un compilateur"]'::jsonb, 0, 'Les blocs servent à la logique, le texte à piloter une carte programmable ou à traiter des données.', 4),
    ('895f9f44-f523-51ff-a4ed-08c2d957dbbc'::uuid, 'technologie', '5e', 'OST et contraintes', 'Que signifie une flexibilité F0 dans un cahier des charges ?', 'mcq', '["Une exigence négociable","Une exigence impérative","Une exigence peu négociable","Une exigence facultative"]'::jsonb, 1, 'F0 est impératif, F1 peu négociable, F2 négociable.', 1),
    ('74ab955c-980d-5245-a62a-70403fe8603e'::uuid, 'technologie', '5e', 'OST et contraintes', '« Être recyclable à 90 % » relève de quelle famille de contraintes ?', 'mcq', '["Économiques","Esthétiques","Environnementales","Ergonomiques"]'::jsonb, 2, 'Recyclabilité, consommation et matériaux interdits sont des contraintes environnementales.', 2),
    ('48ba1547-2e1e-5eb8-9086-f1d96114c050'::uuid, 'technologie', '5e', 'OST et contraintes', 'Laquelle de ces formulations est une vraie exigence ?', 'mcq', '["Le casque doit être léger","Le casque doit être agréable","Le casque doit plaire aux clients","Masse inférieure à 300 g, tolérance ±20 g"]'::jsonb, 3, 'Elle donne un critère (la masse), un niveau (300 g) et une flexibilité (±20 g) : on peut la vérifier.', 3),
    ('f1c5e5f0-3e83-5365-a298-0943e3b53407'::uuid, 'technologie', '5e', 'OST et contraintes', 'Que coûte le plus souvent le fait de rendre un objet plus sûr ?', 'mcq', '["Il devient plus lourd","Il devient moins cher","Il devient plus rapide à fabriquer","Rien, c’est sans contrepartie"]'::jsonb, 0, 'Les contraintes s’opposent : la sécurité ajoute souvent de la matière, donc du poids. Concevoir, c’est arbitrer.', 4),
    ('e66102e7-3191-503c-83eb-3860388e1fce'::uuid, 'technologie', '5e', 'Bases de la programmation', 'Quelle différence y a-t-il entre un algorithme et un programme ?', 'mcq', '["L’algorithme est toujours plus long","Le programme ne contient jamais de boucle","Le programme est la traduction de l’algorithme dans un langage compris par la machine","Il n’y en a aucune"]'::jsonb, 2, 'L’algorithme est la suite d’instructions ; le programme l’écrit dans un langage que la machine exécute.', 1),
    ('877e2393-e597-5d73-8d75-13d4ea0d808c'::uuid, 'technologie', '5e', 'Bases de la programmation', 'Quelle boucle convient pour « répéter tant que le bouton n’est pas appuyé » ?', 'mcq', '["Une boucle bornée","Une boucle non bornée","Une séquence","Une variable"]'::jsonb, 1, 'On ne connaît pas d’avance le nombre de tours : la boucle est non bornée.', 2),
    ('9bd00566-ec13-50a2-9d76-e8d0f8207611'::uuid, 'technologie', '5e', 'Bases de la programmation', 'Dans un organigramme, quelle forme représente un test ?', 'mcq', '["Le rectangle","La flèche","Le cercle","Le losange"]'::jsonb, 3, 'Losanges pour les tests, rectangles pour les actions, flèches pour l’enchaînement.', 3),
    ('676a1286-254c-5813-8779-ec5dd383f421'::uuid, 'technologie', '5e', 'Bases de la programmation', 'Pour un programme, un capteur est…', 'mcq', '["une entrée, que le programme lit","une sortie, que le programme commande","une variable","un opérateur logique"]'::jsonb, 0, 'Le programme lit les capteurs (entrées) et commande les actionneurs (sorties) : c’est le lien avec la chaîne d’information.', 4),
    ('4a752c1e-b81f-5a3a-bc31-23d47bd20db9'::uuid, 'technologie', '5e', 'Critères de choix d’un OST', 'Quelle est la dernière étape d’un tableau multicritère ?', 'mcq', '["Noter chaque case","Additionner les totaux pondérés","Choisir les solutions à comparer","Dessiner chaque solution"]'::jsonb, 1, 'On note les cases, on affecte les coefficients, puis on additionne les totaux pondérés pour départager les solutions.', 1),
    ('b4b18dc8-1e65-509f-acee-3e7e1fc3727d'::uuid, 'technologie', '5e', 'Critères de choix d’un OST', 'Par rapport à une ampoule à filament, une LED…', 'mcq', '["coûte moins cher à l’achat et dure moins longtemps","consomme sept fois plus","coûte plus cher à l’achat mais consomme peu et dure bien plus longtemps","a la même durée de vie"]'::jsonb, 2, 'Son prix d’achat est plus élevé, mais sa faible consommation et sa durée de vie la rendent moins chère au coût global.', 2),
    ('c1b782de-e018-573a-8b9c-5d807a200e91'::uuid, 'technologie', '5e', 'Critères de choix d’un OST', 'Quelle question pose le critère d’encombrement ?', 'mcq', '["Combien de temps sans panne ?","Est-il conforme aux normes ?","Est-il facile à utiliser ?","Tient-il dans l’espace disponible ?"]'::jsonb, 3, 'L’encombrement et la masse vérifient que l’objet trouve sa place ; la fiabilité, l’ergonomie et la sécurité posent les autres questions.', 3),
    ('030e9613-69c6-5866-93bf-9e4105c5616e'::uuid, 'technologie', '5e', 'Critères de choix d’un OST', 'Sur quels critères une solution doit-elle d’abord atteindre le niveau exigé ?', 'mcq', '["Les critères impératifs (F0)","Les critères esthétiques","Les critères négociables (F2)","Le seul critère du prix"]'::jsonb, 0, 'Une solution qui manque un critère F0 est écartée, quel que soit son score ailleurs.', 4),
    ('aba11ec2-1cb8-5dc1-84ba-1d177817849f'::uuid, 'technologie', '5e', 'La circulation de l’information dans un réseau informatique', 'Quel équipement relie les machines d’un même réseau local et aiguille les messages ?', 'mcq', '["Le routeur","Le DNS","Le switch","Le modem"]'::jsonb, 2, 'Le switch travaille dans un même réseau ; le routeur relie deux réseaux différents.', 1),
    ('8a9e69a5-1353-5ed4-b9db-72dd93f16446'::uuid, 'technologie', '5e', 'La circulation de l’information dans un réseau informatique', 'Quel protocole sert au courrier électronique ?', 'mcq', '["HTTP","FTP","HTTPS","SMTP"]'::jsonb, 3, 'SMTP transporte le courrier ; HTTP et HTTPS servent le web, FTP le transfert de fichiers.', 2),
    ('00302782-ada2-5618-8f51-25c25b085500'::uuid, 'technologie', '5e', 'La circulation de l’information dans un réseau informatique', 'Que se passe-t-il si un paquet manque à l’arrivée ?', 'mcq', '["Il est redemandé","Tout le message est perdu","Le routeur le reconstitue au hasard","L’ordinateur s’arrête"]'::jsonb, 0, 'Les paquets numérotés sont réassemblés à l’arrivée, et un paquet manquant est redemandé.', 3),
    ('ec802c11-c9d2-550c-8ddb-8a72783fb304'::uuid, 'technologie', '5e', 'La circulation de l’information dans un réseau informatique', 'Comment appelle-t-on la machine qui demande un service à un serveur ?', 'mcq', '["Le routeur","Le client","Le switch","La box"]'::jsonb, 1, 'Le serveur rend un service, le client le demande : c’est le cas de ton navigateur face à un site web.', 4),
    ('df68ca0b-661e-599e-9ad4-9e4a107f03e4'::uuid, 'technologie', '4e', 'Cycle de vie d’un OST', 'Qu’est-ce que l’obsolescence logicielle ?', 'mcq', '["Une pièce qui n’existe plus","L’arrêt des mises à jour","Un simple effet de mode","Une batterie usée"]'::jsonb, 1, 'L’objet fonctionne encore mais ne reçoit plus de mises à jour ; la pièce introuvable relève de l’obsolescence technique.', 1),
    ('6e87d02d-1f28-542a-b4b7-cf3473f99c2b'::uuid, 'technologie', '4e', 'Cycle de vie d’un OST', 'Quel est le principe du modèle économique linéaire ?', 'mcq', '["Extraire, fabriquer, jeter","Réduire, réemployer, recycler","Réparer avant de remplacer","Louer au lieu d’acheter"]'::jsonb, 0, 'Le modèle linéaire épuise les ressources ; l’économie circulaire cherche à refermer la boucle.', 2),
    ('a69ff6a9-5380-52ed-aae2-1866037e401b'::uuid, 'technologie', '4e', 'Cycle de vie d’un OST', 'Pourquoi un sac réutilisable n’est-il pas forcément plus écologique qu’un sac plastique ?', 'mcq', '["Il ne peut jamais être recyclé","Il est toujours fait en pétrole","Il n’est avantageux qu’après un certain nombre de réemplois","Il pollue pendant son utilisation"]'::jsonb, 2, 'Il coûte plus cher à fabriquer : seule l’analyse du cycle de vie dit à partir de combien d’usages il devient gagnant.', 3),
    ('f43b4b6b-4907-57a1-aa7f-6f21b486e3fd'::uuid, 'technologie', '4e', 'Cycle de vie d’un OST', 'Pourquoi les DEEE ne vont-ils jamais à la poubelle ordinaire ?', 'mcq', '["Ils sont trop lourds","Ils sont trop volumineux","Ils brûlent mal","Ils contiennent des métaux précieux et des substances dangereuses"]'::jsonb, 3, 'Déposés en déchèterie ou en point de collecte, leurs métaux sont récupérés et leurs substances dangereuses traitées.', 4),
    ('d5ea52ae-8ee7-5ea9-83cb-766009a936c4'::uuid, 'technologie', '5e', 'Cycle de vie d’un OST', 'Qu’est-ce que l’obsolescence logicielle ?', 'mcq', '["Une pièce qui n’existe plus","L’arrêt des mises à jour","Un simple effet de mode","Une batterie usée"]'::jsonb, 1, 'L’objet fonctionne encore mais ne reçoit plus de mises à jour ; la pièce introuvable relève de l’obsolescence technique.', 1),
    ('a079e20f-4d4b-5d4e-8aad-09793d238967'::uuid, 'technologie', '5e', 'Cycle de vie d’un OST', 'Quel est le principe du modèle économique linéaire ?', 'mcq', '["Extraire, fabriquer, jeter","Réduire, réemployer, recycler","Réparer avant de remplacer","Louer au lieu d’acheter"]'::jsonb, 0, 'Le modèle linéaire épuise les ressources ; l’économie circulaire cherche à refermer la boucle.', 2),
    ('46ca23ed-badc-5bda-b1e6-6bea3c07c106'::uuid, 'technologie', '5e', 'Cycle de vie d’un OST', 'Pourquoi un sac réutilisable n’est-il pas forcément plus écologique qu’un sac plastique ?', 'mcq', '["Il ne peut jamais être recyclé","Il est toujours fait en pétrole","Il n’est avantageux qu’après un certain nombre de réemplois","Il pollue pendant son utilisation"]'::jsonb, 2, 'Il coûte plus cher à fabriquer : seule l’analyse du cycle de vie dit à partir de combien d’usages il devient gagnant.', 3),
    ('870b7120-95eb-5367-a9f1-b2f2ff958ee1'::uuid, 'technologie', '5e', 'Cycle de vie d’un OST', 'Pourquoi les DEEE ne vont-ils jamais à la poubelle ordinaire ?', 'mcq', '["Ils sont trop lourds","Ils sont trop volumineux","Ils brûlent mal","Ils contiennent des métaux précieux et des substances dangereuses"]'::jsonb, 3, 'Déposés en déchèterie ou en point de collecte, leurs métaux sont récupérés et leurs substances dangereuses traitées.', 4),
    ('a206656b-3f2c-5bb4-907e-8546ddb30862'::uuid, 'technologie', '5e', 'Les OST', 'Pour une lampe de lecture, quelle est la matière d’œuvre ?', 'mcq', '["Le verre de l’ampoule","L’électricité du réseau","La lumière de la pièce","La personne qui lit"]'::jsonb, 2, 'La matière d’œuvre est ce sur quoi l’objet agit : la lampe modifie la lumière de la pièce. Celui qui lit est l’utilisateur.', 1),
    ('04b02d83-7911-5b0a-a2c6-9ac341140fb8'::uuid, 'technologie', '5e', 'Les OST', 'Lequel de ces exemples est un système technique ?', 'mcq', '["Un tournevis","Une chaise","Un marteau","Un ascenseur"]'::jsonb, 3, 'Un ascenseur associe plusieurs objets qui travaillent ensemble, avec électronique et programme ; les trois autres répondent au besoin par eux-mêmes.', 2),
    ('05247d0e-6278-5b4f-b51b-476e60863b85'::uuid, 'technologie', '5e', 'Les OST', 'Quelle fonction d’usage le vélo garde-t-il depuis 150 ans ?', 'mcq', '["Se déplacer","Freiner","Transmettre le mouvement","Éclairer"]'::jsonb, 0, 'Sa fonction d’usage n’a pas changé ; ses matériaux, sa transmission, ses freins et son assistance électrique, si.', 3),
    ('8c45a3e4-1dc6-5af6-9d9e-6ac228d2a3ab'::uuid, 'technologie', '5e', 'Les OST', 'La bougie, la lampe à huile, l’ampoule et la LED forment…', 'mcq', '["une lignée d’objets techniques","une famille d’objets techniques","un système technique","une chaîne d’énergie"]'::jsonb, 1, 'Ils remplissent la même fonction d’usage, éclairer, par des solutions différentes : c’est une famille.', 4),
