    ('32ecd121-c2d2-502d-b963-1b9cbb77df92'::uuid, 'technologie', '4e', 'OST et contraintes', 'Que signifie une flexibilité F0 dans un cahier des charges ?', 'mcq', '["Une exigence négociable","Une exigence impérative","Une exigence peu négociable","Une exigence facultative"]'::jsonb, 1, 'F0 est impératif, F1 peu négociable, F2 négociable.', 1),
    ('4e728727-e99a-5bc0-a435-7f8233f727d9'::uuid, 'technologie', '4e', 'OST et contraintes', '« Être recyclable à 90 % » relève de quelle famille de contraintes ?', 'mcq', '["Économiques","Esthétiques","Environnementales","Ergonomiques"]'::jsonb, 2, 'Recyclabilité, consommation et matériaux interdits sont des contraintes environnementales.', 2),
    ('c98887d2-1993-54a6-b208-cd4327d5dbd4'::uuid, 'technologie', '4e', 'OST et contraintes', 'Laquelle de ces formulations est une vraie exigence ?', 'mcq', '["Le casque doit être léger","Le casque doit être agréable","Le casque doit plaire aux clients","Masse inférieure à 300 g, tolérance ±20 g"]'::jsonb, 3, 'Elle donne un critère (la masse), un niveau (300 g) et une flexibilité (±20 g) : on peut la vérifier.', 3),
    ('34955466-432a-5bd7-9e8a-9ac6bfa9ec58'::uuid, 'technologie', '4e', 'OST et contraintes', 'Que coûte le plus souvent le fait de rendre un objet plus sûr ?', 'mcq', '["Il devient plus lourd","Il devient moins cher","Il devient plus rapide à fabriquer","Rien, c’est sans contrepartie"]'::jsonb, 0, 'Les contraintes s’opposent : la sécurité ajoute souvent de la matière, donc du poids. Concevoir, c’est arbitrer.', 4),
    ('9dff6fe9-b052-5a66-8c64-b2acaa2d5c08'::uuid, 'technologie', '5e', 'Procédés de fabrication', 'Quel est l’atout principal de la fabrication par déformation ?', 'mcq', '["Aucun outillage n’est nécessaire","Aucune perte de matière","Elle est idéale pour une pièce unique","Elle produit des pièces creuses complexes couche par couche"]'::jsonb, 1, 'La matière change de forme sans copeaux ; l’outillage est en revanche coûteux, ce qui la réserve aux séries.', 1),
    ('495dd7b0-e4d4-591b-849f-a5ae5b41acd3'::uuid, 'technologie', '5e', 'Procédés de fabrication', 'Quel procédé convient à cent mille pièces en plastique ?', 'mcq', '["L’impression 3D","Le sciage","L’injection plastique","Le ponçage"]'::jsonb, 2, 'L’injection est rapide et répétable en grande série ; l’impression 3D est trop lente pour cela.', 2),
    ('bb2e8bc5-51b4-5c6f-b66e-401cb3aa6e78'::uuid, 'technologie', '5e', 'Procédés de fabrication', 'À quelle famille appartient le rivetage ?', 'mcq', '["À l’assemblage démontable","À l’enlèvement de matière","À l’ajout de matière","À l’assemblage non démontable"]'::jsonb, 3, 'Comme la soudure et le collage, le rivet est résistant mais définitif.', 3),
    ('a60ab556-9566-50e8-9b42-2cdab98a467a'::uuid, 'technologie', '5e', 'Procédés de fabrication', 'Quelle est la limite de l’impression 3D ?', 'mcq', '["Elle est lente pour produire en série","Elle produit beaucoup de copeaux","Elle ne permet pas les formes complexes","Elle exige un outillage coûteux"]'::jsonb, 0, 'Idéale pour un prototype ou une forme complexe, elle construit couche par couche : trop lente pour une grande série.', 4),
    ('e5ccceae-80a6-5a24-9fd6-e8d282c499bb'::uuid, 'technologie', '5e', 'La chaîne d’énergie', 'Dans quelle fonction range-t-on une résistance chauffante ?', 'mcq', '["Alimenter","Distribuer","Convertir","Transmettre"]'::jsonb, 2, 'Elle transforme l’énergie électrique en chaleur : c’est un actionneur, qui assure la fonction « convertir ».', 1),
    ('9addfa3e-1961-5554-963e-6ed6002010d1'::uuid, 'technologie', '5e', 'La chaîne d’énergie', 'Comment appelle-t-on le résultat final de la chaîne d’énergie ?', 'mcq', '["L’acquisition","L’action","La consigne","Le traitement"]'::jsonb, 1, 'L’action, c’est la roue qui tourne, la porte qui s’ouvre ou l’air qui se réchauffe.', 2),
    ('767a8abe-67b8-5de4-8b99-8425276abb19'::uuid, 'technologie', '5e', 'La chaîne d’énergie', 'Dans un portail automatique, quelle fonction assure le réseau 230 V ?', 'mcq', '["Convertir","Distribuer","Transmettre","Alimenter"]'::jsonb, 3, 'Le réseau fournit l’énergie ; le relais la distribue, le moteur la convertit, le réducteur et la crémaillère la transmettent.', 3),
    ('c0be64d7-8c4b-5dc9-8502-f2f390ef248f'::uuid, 'technologie', '5e', 'La chaîne d’énergie', 'Quel rôle joue un réducteur dans la chaîne d’énergie ?', 'mcq', '["Il transmet le mouvement en adaptant vitesse et effort","Il fournit l’énergie","Il laisse passer ou coupe l’énergie sur ordre","Il convertit l’énergie électrique en énergie mécanique"]'::jsonb, 0, 'Le réducteur appartient à la fonction « transmettre » : il ralentit le mouvement pour gagner de l’effort.', 4),
    ('1a2f2854-5655-53ee-b3fb-54addf16ac3b'::uuid, 'technologie', '4e', 'Règles de sécurité', 'Que signifie un pictogramme carré vert ?', 'mcq', '["Une interdiction","Un danger","Une information de secours","Une obligation"]'::jsonb, 2, 'Le carré vert signale une issue de secours ou une trousse de premiers soins.', 1),
    ('dfac0b99-80b2-54ca-9ff8-6f5e93f33298'::uuid, 'technologie', '4e', 'Règles de sécurité', 'De quelles couleurs est le bouton d’arrêt d’urgence ?', 'mcq', '["Vert sur fond blanc","Rouge sur fond jaune","Bleu sur fond rouge","Noir sur fond jaune"]'::jsonb, 1, 'Rouge sur fond jaune, il coupe immédiatement l’alimentation de la machine.', 2),
    ('8c5cbc07-fc7e-59ab-af01-faca9fedcc9b'::uuid, 'technologie', '4e', 'Règles de sécurité', 'Quelle tenue est exigée en atelier ?', 'mcq', '["Des gants en permanence","Une écharpe pour se protéger","Des sandales pour être à l’aise","Cheveux attachés, aucun bijou ni écharpe"]'::jsonb, 3, 'Cheveux, bijoux et écharpes peuvent être happés par une pièce en rotation ; il faut aussi une blouse et des chaussures fermées.', 3),
    ('75ecb1e0-7e27-551a-b549-8df076641d82'::uuid, 'technologie', '4e', 'Règles de sécurité', 'Que faut-il faire si l’on remarque un câble abîmé sur une machine ?', 'mcq', '["Le signaler","Continuer en faisant attention","Le réparer soi-même avec du ruban adhésif","L’ignorer si la machine fonctionne"]'::jsonb, 0, 'Toute anomalie — câble abîmé, bruit inhabituel — se signale avant de continuer.', 4),
    ('092616d5-ee5a-587c-b632-777039f85adf'::uuid, 'technologie', '5e', 'La chaîne d’information', 'Quel composant acquiert une information sur la lumière ambiante ?', 'mcq', '["Le buzzer","La photorésistance","Le microcontrôleur","Le moteur"]'::jsonb, 1, 'La photorésistance est un capteur de lumière : elle assure la fonction « acquérir ».', 1),
    ('d584c514-246d-56db-a60f-3292baa6adf2'::uuid, 'technologie', '5e', 'La chaîne d’information', 'Quelle fonction de la chaîne d’information assure un buzzer ?', 'mcq', '["Acquérir","Traiter","Communiquer","Alimenter"]'::jsonb, 2, 'Il transmet une information à l’utilisateur par un son, comme l’écran ou la LED.', 2),
    ('dec88a1e-7c82-5fe5-ab9b-f426a4c94900'::uuid, 'technologie', '5e', 'La chaîne d’information', 'Qu’exécute la partie commande pour décider quoi faire ?', 'mcq', '["Une conversion d’énergie","Une mesure","Un signal lumineux","Un programme"]'::jsonb, 3, 'Le microcontrôleur, la carte programmable ou l’automate exécutent un programme : c’est la fonction « traiter ».', 3),
    ('5801b362-ad6e-5145-98da-56082b4fabee'::uuid, 'technologie', '5e', 'La chaîne d’information', 'Lequel de ces moyens permet de communiquer sans fil ?', 'mcq', '["Le Bluetooth","Le fin de course","La thermistance","Le vérin"]'::jsonb, 0, 'Le Bluetooth, le Wi-Fi ou la radio transmettent l’information à un autre système ; le fin de course et la thermistance sont des capteurs.', 4),
    ('df96cb31-74c9-562d-88d6-3760fc56dc15'::uuid, 'technologie', '5e', 'OST et interacteurs extérieurs', 'Pour un lampadaire de rue, « résister aux intempéries » est…', 'mcq', '["la fonction principale","une fonction contrainte","une solution technique","un principe technique"]'::jsonb, 1, 'Elle relie l’objet à un seul interacteur, le milieu : c’est une fonction contrainte.', 1),
    ('a8779e89-582b-5aa1-bed7-25519265efff'::uuid, 'technologie', '5e', 'OST et interacteurs extérieurs', 'Lequel de ces interacteurs fait partie du milieu ?', 'mcq', '["L’utilisateur","Le budget","La poussière","Les normes"]'::jsonb, 2, 'Le milieu, c’est l’air, l’eau, la température, la poussière ou les vibrations qui entourent l’objet.', 2),
    ('35b7576c-5ea7-557c-ad41-7deaa0b70ade'::uuid, 'technologie', '5e', 'OST et interacteurs extérieurs', 'Quels interacteurs la fonction principale du lampadaire relie-t-elle ?', 'mcq', '["Le réseau électrique et le budget","Les intempéries et les normes","Le paysage urbain et la commune","Le piéton et la chaussée"]'::jsonb, 3, 'La fonction principale relie deux interacteurs à travers l’objet : permettre au piéton de voir la chaussée la nuit.', 3),
    ('af1ae3ea-6b4e-55e1-97be-0575f2811f3d'::uuid, 'technologie', '5e', 'OST et interacteurs extérieurs', 'Parmi ces interacteurs, lequel impose une limite de conception plutôt qu’un élément physique ?', 'mcq', '["L’énergie","Le budget","La matière d’œuvre","Le milieu"]'::jsonb, 1, 'Le budget, comme l’esthétique, ne touche pas l’objet physiquement : il borne les choix du concepteur.', 4),
    ('7768f787-9e44-5791-9017-9a7cdbb76a3c'::uuid, 'technologie', '5e', 'Écrire mettre au point et exécuter un programme simple', 'Un programme s’arrête en cours de route à cause d’une division par zéro. De quelle erreur s’agit-il ?', 'mcq', '["Une erreur de syntaxe","Une erreur de logique","Une erreur d’exécution","Une erreur d’ergonomie"]'::jsonb, 2, 'Le programme a démarré, puis s’arrête : c’est une erreur d’exécution, comme un capteur absent.', 1),
    ('6d794632-e918-5abd-8992-3cf9aed84234'::uuid, 'technologie', '5e', 'Écrire mettre au point et exécuter un programme simple', 'Quel nom de variable est le plus explicite ?', 'mcq', '["v2","x","a1","vitesse"]'::jsonb, 3, 'Un nom explicite rend le programme lisible par un autre, ou par soi-même trois mois plus tard.', 2),
    ('a33caa2b-b213-5b23-9f73-9745bc23d18a'::uuid, 'technologie', '5e', 'Écrire mettre au point et exécuter un programme simple', 'Quelle technique aide à voir où le comportement d’un programme dévie ?', 'mcq', '["Supprimer les commentaires","Afficher les valeurs intermédiaires","Raccourcir les noms de variables","Relancer sans rien changer"]'::jsonb, 1, 'Afficher les valeurs en cours de route, ou exécuter pas à pas, montre l’endroit exact où le programme s’écarte de l’attendu.', 3),
    ('902ddcff-4c18-5b7b-b532-12edea6209b7'::uuid, 'technologie', '5e', 'Écrire mettre au point et exécuter un programme simple', 'Que contient un bon jeu d’essai ?', 'mcq', '["Un cas normal, un cas limite et un cas interdit","Uniquement des cas qui fonctionnent","Un seul cas bien choisi","Les cas proposés par l’utilisateur, sans plus"]'::jsonb, 0, 'Le cas normal vérifie le fonctionnement, le cas limite et le cas interdit révèlent les défauts.', 4),
    ('3fb09fcd-42c0-5083-ae3d-b7c402817d35'::uuid, 'technologie', '4e', 'Procédés de fabrication', 'Quel est l’atout principal de la fabrication par déformation ?', 'mcq', '["Aucun outillage n’est nécessaire","Aucune perte de matière","Elle est idéale pour une pièce unique","Elle produit des pièces creuses complexes couche par couche"]'::jsonb, 1, 'La matière change de forme sans copeaux ; l’outillage est en revanche coûteux, ce qui la réserve aux séries.', 1),
    ('24b750f1-17d4-5cb4-89a2-89f254a04d91'::uuid, 'technologie', '4e', 'Procédés de fabrication', 'Quel procédé convient à cent mille pièces en plastique ?', 'mcq', '["L’impression 3D","Le sciage","L’injection plastique","Le ponçage"]'::jsonb, 2, 'L’injection est rapide et répétable en grande série ; l’impression 3D est trop lente pour cela.', 2),
    ('f60ad211-ba7b-54b0-9b60-036c3638c2b7'::uuid, 'technologie', '4e', 'Procédés de fabrication', 'À quelle famille appartient le rivetage ?', 'mcq', '["À l’assemblage démontable","À l’enlèvement de matière","À l’ajout de matière","À l’assemblage non démontable"]'::jsonb, 3, 'Comme la soudure et le collage, le rivet est résistant mais définitif.', 3),
    ('0fb28952-2234-51d4-917e-3be140da6eab'::uuid, 'technologie', '4e', 'Procédés de fabrication', 'Quelle est la limite de l’impression 3D ?', 'mcq', '["Elle est lente pour produire en série","Elle produit beaucoup de copeaux","Elle ne permet pas les formes complexes","Elle exige un outillage coûteux"]'::jsonb, 0, 'Idéale pour un prototype ou une forme complexe, elle construit couche par couche : trop lente pour une grande série.', 4),
    ('9c6fcda5-79bb-5c49-b1f5-dc027bb4f42f'::uuid, 'technologie', '4e', 'Les mécanismes de transmission et de transformation de mouvements', 'Quel mécanisme transforme une rotation en translation lente et puissante, comme dans un étau ?', 'mcq', '["Le pignon-crémaillère","La vis-écrou","La bielle-manivelle","Les roues de friction"]'::jsonb, 1, 'La vis-écrou avance peu à chaque tour, mais avec beaucoup de force : étau, presse.', 1),
    ('5efcb84e-cbaf-5171-8c0a-88f4d12eee90'::uuid, 'technologie', '4e', 'Les mécanismes de transmission et de transformation de mouvements', 'Dans quel sens tournent les deux pignons reliés par la chaîne d’un vélo ?', 'mcq', '["En sens inverse","Alternativement dans un sens puis dans l’autre","Dans le même sens","Cela dépend du nombre de dents"]'::jsonb, 2, 'Avec une chaîne, les pignons tournent dans le même sens ; deux engrenages en contact direct tournent en sens inverse.', 2),
    ('7d00c672-3308-5a18-ab77-13e054a07569'::uuid, 'technologie', '4e', 'Les mécanismes de transmission et de transformation de mouvements', 'Un pignon d’entrée de 20 dents entraîne une roue de sortie de 60 dents. Que vaut le rapport de transmission ?', 'mcq', '["3","40","1/40","1/3"]'::jsonb, 3, 'r = dents de l’entrée ÷ dents de la sortie = 20 ÷ 60 = 1/3 : r < 1, c’est un réducteur.', 3),
    ('ea0e64d0-5aaf-5967-b6ba-4bf05e2e2564'::uuid, 'technologie', '4e', 'Les mécanismes de transmission et de transformation de mouvements', 'Quel mécanisme actionne les soupapes d’un moteur ?', 'mcq', '["Came et poussoir","Poulies-courroie","Pignons-chaîne","Engrenages"]'::jsonb, 0, 'La came transforme la rotation en translation alternative du poussoir, qui ouvre et ferme la soupape.', 4),
    ('be3df379-93d1-5b9c-b8ab-4ab0202d33ba'::uuid, 'technologie', '4e', 'La chaîne d’énergie', 'Dans quelle fonction range-t-on une résistance chauffante ?', 'mcq', '["Alimenter","Distribuer","Convertir","Transmettre"]'::jsonb, 2, 'Elle transforme l’énergie électrique en chaleur : c’est un actionneur, qui assure la fonction « convertir ».', 1),
    ('1d45de91-2016-583d-ab7d-58a07022b37c'::uuid, 'technologie', '4e', 'La chaîne d’énergie', 'Comment appelle-t-on le résultat final de la chaîne d’énergie ?', 'mcq', '["L’acquisition","L’action","La consigne","Le traitement"]'::jsonb, 1, 'L’action, c’est la roue qui tourne, la porte qui s’ouvre ou l’air qui se réchauffe.', 2),
    ('a03d0e22-f00a-5b47-b1ff-7796af074fd5'::uuid, 'technologie', '4e', 'La chaîne d’énergie', 'Dans un portail automatique, quelle fonction assure le réseau 230 V ?', 'mcq', '["Convertir","Distribuer","Transmettre","Alimenter"]'::jsonb, 3, 'Le réseau fournit l’énergie ; le relais la distribue, le moteur la convertit, le réducteur et la crémaillère la transmettent.', 3),
    ('268ac552-2220-563b-9062-66f47b81db59'::uuid, 'technologie', '4e', 'La chaîne d’énergie', 'Quel rôle joue un réducteur dans la chaîne d’énergie ?', 'mcq', '["Il transmet le mouvement en adaptant vitesse et effort","Il fournit l’énergie","Il laisse passer ou coupe l’énergie sur ordre","Il convertit l’énergie électrique en énergie mécanique"]'::jsonb, 0, 'Le réducteur appartient à la fonction « transmettre » : il ralentit le mouvement pour gagner de l’effort.', 4),
    ('d6c25ab0-e056-5f21-9382-dda495442888'::uuid, 'technologie', '4e', 'Système d’information et stockage de données', 'Combien de bits compte un octet ?', 'mcq', '["8","2","10","16"]'::jsonb, 0, 'Un octet vaut 8 bits et code à peu près un caractère.', 1),
    ('b1e69dc7-9755-5b86-8390-1590cb1c21c7'::uuid, 'technologie', '4e', 'Système d’information et stockage de données', 'Qu’apporte l’authentification à deux facteurs ?', 'mcq', '["Elle chiffre le disque","Elle double l’espace de stockage","Le mot de passe seul ne suffit plus pour entrer dans le compte","Elle supprime le mot de passe"]'::jsonb, 2, 'Un second élément, comme un code reçu sur le téléphone, est exigé : un mot de passe volé ne suffit plus.', 2),
    ('857a6c26-9d0d-5ec2-8bc7-d7e8f81da673'::uuid, 'technologie', '4e', 'Système d’information et stockage de données', 'Quelle est la limite d’un stockage dans le nuage ?', 'mcq', '["Il n’est accessible que d’un seul endroit","Il ne peut pas être sauvegardé","Il est interdit par le RGPD","Il dépend du réseau et du prestataire"]'::jsonb, 3, 'Accessible de partout, il exige une connexion et dépend d’un prestataire, dont les centres de données sont bien réels.', 3),
    ('0defd815-d496-59e5-a9e0-b345ca98ca93'::uuid, 'technologie', '4e', 'Système d’information et stockage de données', 'Quel principe du RGPD impose de dire à quoi serviront les données collectées ?', 'mcq', '["Le consentement","La finalité","La durée de conservation","Le droit de rectification"]'::jsonb, 1, 'La finalité de la collecte doit être déclarée ; le consentement, lui, doit être explicite.', 4),
    ('1829f5f2-931e-565c-8fc5-9fd427a5b4d0'::uuid, 'technologie', '5e', 'Matériaux et procédés', 'Quel est le principal défaut des céramiques ?', 'mcq', '["Elles conduisent l’électricité","Elles rouillent","Elles sont fragiles : elles cassent sans se déformer","Elles sont trop légères"]'::jsonb, 2, 'Très dures et résistantes à la chaleur, elles cassent pourtant d’un coup, sans se déformer avant.', 1),
    ('51232316-20c5-513d-9de6-d5ecd8110511'::uuid, 'technologie', '5e', 'Matériaux et procédés', 'Que désigne la ductilité d’un matériau ?', 'mcq', '["Sa résistance à la rayure","Sa capacité à être étiré en fil","Sa capacité à conduire la chaleur","Sa capacité à reprendre sa forme"]'::jsonb, 1, 'Un matériau ductile, comme le cuivre, s’étire en fil sans rompre.', 2),
    ('bc90d859-99d7-5290-803d-3549b68f9a5a'::uuid, 'technologie', '5e', 'Matériaux et procédés', 'À quelle famille de matériaux appartient le bois ?', 'mcq', '["Aux métalliques","Aux céramiques","Aux composites","Aux organiques"]'::jsonb, 3, 'Le bois, comme les plastiques, le cuir et le papier, est un matériau organique.', 3),
    ('5b84fd13-2f01-5299-b67c-4cfd49dbf167'::uuid, 'technologie', '5e', 'Matériaux et procédés', 'Pourquoi un composite plastique est-il difficile à recycler ?', 'mcq', '["Ses matériaux sont quasi impossibles à séparer","Il est trop dur pour être broyé","Il contient toujours du métal","Il est interdit en déchèterie"]'::jsonb, 0, 'Un composite cumule les qualités de deux matériaux, mais on ne sait presque pas les séparer en fin de vie.', 4),
    ('8b1ffefb-b773-5c94-ad73-8f66fca23088'::uuid, 'technologie', '5e', 'La fonction technique et le principe technique', 'Sur quel principe technique reposent tous les freins de vélo ?', 'mcq', '["La gravité","Le magnétisme","Le frottement","La dilatation"]'::jsonb, 2, 'Patins, disque ou rétropédalage : ces solutions différentes exploitent toutes le frottement.', 1),
    ('89a36bd9-4f8d-53d0-91d9-4c7ad73440dc'::uuid, 'technologie', '5e', 'La fonction technique et le principe technique', 'Comment exprime-t-on une fonction d’usage ?', 'mcq', '["Par un verbe à l’infinitif","Par un nombre","Par le nom d’un composant","Par une unité de mesure"]'::jsonb, 0, 'On écrit le service rendu par un verbe à l’infinitif : « se déplacer », « éclairer ».', 2),
    ('6f39067c-fe17-5809-8c12-01920c0345d1'::uuid, 'technologie', '5e', 'La fonction technique et le principe technique', 'Pour un vélo, lequel de ces éléments est une solution technique ?', 'mcq', '["Freiner","Le frottement","Se déplacer","Un frein à disque"]'::jsonb, 3, 'Le frein à disque est le composant concret retenu ; freiner est une fonction technique, le frottement un principe, se déplacer la fonction d’usage.', 3),
    ('19ad659d-f8bb-5950-9deb-26f6b5820333'::uuid, 'technologie', '5e', 'La fonction technique et le principe technique', 'Dans l’exigence « distance de freinage : moins de 5 m à 20 km/h », que désigne « moins de 5 m » ?', 'mcq', '["Le critère","Le niveau","La fonction d’usage","Le principe technique"]'::jsonb, 1, 'Le critère est ce qu’on mesure (la distance de freinage) ; le niveau est la valeur à atteindre.', 4),
    ('9a018c41-0575-5205-8bb7-309abec42afd'::uuid, 'technologie', '4e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Quel essai consiste à charger une pièce en son milieu, appuyée à ses extrémités ?', 'mcq', '["L’essai de traction","L’essai de compression","L’essai de flexion","L’essai de torsion"]'::jsonb, 2, 'La flexion fait plier la pièce ; la traction l’étire, la compression l’écrase, la torsion la vrille.', 1),
    ('4a539fb9-147e-5cad-967d-e0be01df426c'::uuid, 'technologie', '4e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Pourquoi note-t-on l’incertitude d’une mesure ?', 'mcq', '["Pour rendre le résultat plus précis","Parce qu’une mesure sans incertitude n’en est pas une","Parce qu’elle remplace les conditions d’essai","Pour éviter de refaire l’essai"]'::jsonb, 1, 'Toute mesure a une marge d’erreur : sans elle, on ne peut pas juger si l’exigence est vraiment atteinte.', 2),
    ('305208e1-1593-5ae5-9951-d45f5e4274e1'::uuid, 'technologie', '4e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Lequel de ces essais est un essai de performance ?', 'mcq', '["L’essai de traction","L’essai de torsion","L’essai de fatigue","La mesure de l’autonomie"]'::jsonb, 3, 'L’autonomie, la vitesse ou le niveau sonore sont des performances ; les trois autres sont des essais de tenue mécanique.', 3),
    ('e9280926-327e-580b-acff-035710e63fc6'::uuid, 'technologie', '4e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Quel verdict écrit-on pour chaque exigence, à la fin d’une validation ?', 'mcq', '["Conforme ou non conforme","Bon ou mauvais","Rapide ou lent","Cher ou bon marché"]'::jsonb, 0, 'On compare la valeur mesurée au niveau exigé et on conclut : conforme ou non conforme.', 4),
    ('5b413e60-25e2-5402-a643-03a7023e95fc'::uuid, 'technologie', '4e', 'Structuration et traitement des données', 'Dans un tableau de données, que représente une colonne ?', 'mcq', '["Un enregistrement","Un champ","Une clé","Un filtre"]'::jsonb, 1, 'Une colonne est un champ (nom, date, valeur) ; une ligne est un enregistrement.', 1),
    ('10dc20c4-c7e5-551f-a061-fc21bb4e5072'::uuid, 'technologie', '4e', 'Structuration et traitement des données', 'Quel type de données permet de tester « vrai » ou « faux » ?', 'mcq', '["Le texte","La date","Le nombre décimal","Le booléen"]'::jsonb, 3, 'Un booléen ne prend que deux valeurs, vrai ou faux : il sert aux tests.', 2),
    ('7e66ccdb-30f6-5775-b695-cecebbe31805'::uuid, 'technologie', '4e', 'Structuration et traitement des données', 'Quel graphique montre une répartition, les parts d’un tout ?', 'mcq', '["La courbe","L’histogramme","Le camembert","Le nuage de points"]'::jsonb, 2, 'Le camembert raconte une répartition ; la courbe une évolution, l’histogramme une comparaison.', 3),
    ('3f79055f-8a49-522f-a89f-4496b2bb4f64'::uuid, 'technologie', '4e', 'Structuration et traitement des données', 'Quel format d’échange organise les données en couples nom-valeur ?', 'mcq', '["JSON","CSV","JPEG","MP3"]'::jsonb, 0, 'Le JSON est très utilisé par les objets connectés et les sites web ; le CSV est un tableau en texte.', 4),
    ('4ea706fa-7d43-53d6-b46f-b80558d26cae'::uuid, 'technologie', '4e', 'Matériaux et procédés', 'Quel est le principal défaut des céramiques ?', 'mcq', '["Elles conduisent l’électricité","Elles rouillent","Elles sont fragiles : elles cassent sans se déformer","Elles sont trop légères"]'::jsonb, 2, 'Très dures et résistantes à la chaleur, elles cassent pourtant d’un coup, sans se déformer avant.', 1),
    ('76cfe265-7b9f-5fb8-a2fa-9347f9771bb0'::uuid, 'technologie', '4e', 'Matériaux et procédés', 'Que désigne la ductilité d’un matériau ?', 'mcq', '["Sa résistance à la rayure","Sa capacité à être étiré en fil","Sa capacité à conduire la chaleur","Sa capacité à reprendre sa forme"]'::jsonb, 1, 'Un matériau ductile, comme le cuivre, s’étire en fil sans rompre.', 2),
    ('6b3f04dc-e629-5f79-8d7c-1fd636d76941'::uuid, 'technologie', '4e', 'Matériaux et procédés', 'À quelle famille de matériaux appartient le bois ?', 'mcq', '["Aux métalliques","Aux céramiques","Aux composites","Aux organiques"]'::jsonb, 3, 'Le bois, comme les plastiques, le cuir et le papier, est un matériau organique.', 3),
    ('9a44105c-959a-5e6e-a7dc-e1509b3e5cb9'::uuid, 'technologie', '4e', 'Matériaux et procédés', 'Pourquoi un composite plastique est-il difficile à recycler ?', 'mcq', '["Ses matériaux sont quasi impossibles à séparer","Il est trop dur pour être broyé","Il contient toujours du métal","Il est interdit en déchèterie"]'::jsonb, 0, 'Un composite cumule les qualités de deux matériaux, mais on ne sait presque pas les séparer en fin de vie.', 4),
    ('3ce69846-226c-5ae9-ad40-2d49d05470e0'::uuid, 'technologie', '4e', 'OST et interacteurs extérieurs', 'Pour un lampadaire de rue, « résister aux intempéries » est…', 'mcq', '["la fonction principale","une fonction contrainte","une solution technique","un principe technique"]'::jsonb, 1, 'Elle relie l’objet à un seul interacteur, le milieu : c’est une fonction contrainte.', 1),
    ('b59de7e5-ad25-51cf-a86e-158edda7c2d8'::uuid, 'technologie', '4e', 'OST et interacteurs extérieurs', 'Lequel de ces interacteurs fait partie du milieu ?', 'mcq', '["L’utilisateur","Le budget","La poussière","Les normes"]'::jsonb, 2, 'Le milieu, c’est l’air, l’eau, la température, la poussière ou les vibrations qui entourent l’objet.', 2),
    ('cf0faec2-c45a-5035-aa05-b9e35078660a'::uuid, 'technologie', '4e', 'OST et interacteurs extérieurs', 'Quels interacteurs la fonction principale du lampadaire relie-t-elle ?', 'mcq', '["Le réseau électrique et le budget","Les intempéries et les normes","Le paysage urbain et la commune","Le piéton et la chaussée"]'::jsonb, 3, 'La fonction principale relie deux interacteurs à travers l’objet : permettre au piéton de voir la chaussée la nuit.', 3),
    ('32074469-9ce8-55f7-b274-a4cbc31b27cd'::uuid, 'technologie', '4e', 'OST et interacteurs extérieurs', 'Parmi ces interacteurs, lequel impose une limite de conception plutôt qu’un élément physique ?', 'mcq', '["L’énergie","Le budget","La matière d’œuvre","Le milieu"]'::jsonb, 1, 'Le budget, comme l’esthétique, ne touche pas l’objet physiquement : il borne les choix du concepteur.', 4),
    ('169dc251-5207-51aa-9cf5-7f9e3ad5d9ab'::uuid, 'technologie', '4e', 'Organisation d’un projet technique', 'Que porte l’axe horizontal d’un diagramme de Gantt ?', 'mcq', '["Les tâches","Le temps","Les coûts","Les responsables"]'::jsonb, 1, 'Le temps est en abscisse, les tâches en ordonnée ; la longueur de chaque barre est la durée de la tâche.', 1),
    ('c6392259-1dc8-5a86-9931-f56bfd829f15'::uuid, 'technologie', '4e', 'Organisation d’un projet technique', 'De quoi dispose une tâche qui n’est pas sur le chemin critique ?', 'mcq', '["D’un budget supplémentaire","D’une priorité absolue","D’une marge","D’aucun responsable"]'::jsonb, 2, 'Elle peut prendre un peu de retard sans décaler la fin du projet, ce qui est impossible sur le chemin critique.', 2),
    ('f521bb59-35d1-5d42-b514-ab6620d9df9b'::uuid, 'technologie', '4e', 'Organisation d’un projet technique', 'Quelle phase vient juste après l’analyse du besoin ?', 'mcq', '["La réalisation","Le bilan","La conception","La recherche de solutions"]'::jsonb, 3, 'Après le cahier des charges, on cherche et compare plusieurs pistes, avant de concevoir.', 3),
    ('482066cc-ca82-5bb1-a2aa-b6f6e76f198f'::uuid, 'technologie', '4e', 'Organisation d’un projet technique', 'Quel document garde les décisions et les essais ratés d’un projet ?', 'mcq', '["Le carnet de bord","Le diagramme de Gantt","La nomenclature","Le cahier des charges"]'::jsonb, 0, 'Le carnet de bord assure la traçabilité : il évite qu’un autre refasse la même erreur.', 4),
    ('dc6d38c7-f8be-544f-aff5-a5a999dde678'::uuid, 'technologie', '5e', 'Prototypage de solutions', 'Quel degré de prototype valide le procédé de fabrication autant que l’objet ?', 'mcq', '["La maquette","Le prototype fonctionnel","La présérie","Le croquis"]'::jsonb, 2, 'La présérie utilise déjà les matériaux et les procédés du produit final.', 1),
    ('fbf9c650-b9ab-56ea-bf7a-67b34c7ee235'::uuid, 'technologie', '5e', 'Prototypage de solutions', 'Quel moyen permet de prototyper l’électronique sans soudure ?', 'mcq', '["La découpe vinyle","Le carton plume","L’impression 3D","Les cartes programmables et les modules enfichables"]'::jsonb, 3, 'Les modules s’enfichent sur la carte : on peut tester et modifier le montage en quelques minutes.', 2),
    ('72addf60-9fd4-592d-95a9-b05cbb72c85b'::uuid, 'technologie', '5e', 'Prototypage de solutions', 'Combien coûte une erreur découverte sur dix mille exemplaires vendus, par rapport à la même erreur trouvée sur un prototype ?', 'mcq', '["Deux fois plus","Cent fois plus","Dix fois moins","Autant"]'::jsonb, 1, 'Plus une erreur est découverte tard, plus elle coûte : c’est pour cela qu’on prototype avant de produire.', 3),
    ('b5143d63-6580-51d7-8922-cdf27801ee33'::uuid, 'technologie', '5e', 'Prototypage de solutions', 'Que faut-il noter en documentant un prototype ?', 'mcq', '["Photos, mesures, difficultés, modifications et leurs raisons","Seulement le résultat final","Seulement le coût","Seulement les photos"]'::jsonb, 0, 'Cette mémoire du projet nourrit le dossier final et explique chaque choix.', 4),
    ('6c4272b0-9087-505f-9d87-00d5d189b66e'::uuid, 'technologie', '4e', 'Modes de représentation d’un OST', 'Que signifie une échelle 2:1 ?', 'mcq', '["Le dessin est deux fois plus petit que l’objet","Le dessin est deux fois plus grand que l’objet","Le dessin est à taille réelle","L’objet mesure 2 cm"]'::jsonb, 1, 'Le premier nombre concerne le dessin : 2:1 agrandit deux fois, 1:2 réduit deux fois, 1:1 est la grandeur nature.', 1),
    ('3e83cbea-c07d-5c52-a6ff-455fb98a7b49'::uuid, 'technologie', '4e', 'Modes de représentation d’un OST', 'Quel trait représente un axe sur un dessin technique ?', 'mcq', '["Le trait continu fort","Le trait interrompu","Le trait mixte fin","Le trait ondulé"]'::jsonb, 2, 'Le trait continu fort montre une arête vue, l’interrompu une arête cachée, le mixte fin un axe.', 2),
    ('cd3755b8-0193-54af-8729-f51d3ec04c58'::uuid, 'technologie', '4e', 'Modes de représentation d’un OST', 'Quel schéma représente les composants normalisés d’un circuit ?', 'mcq', '["Le schéma de principe","Le schéma cinématique","Le croquis","Le schéma électrique"]'::jsonb, 3, 'Le schéma électrique utilise les symboles normalisés des composants ; le cinématique montre les liaisons et les mouvements.', 3),
    ('72196ac4-1f22-5b81-876c-ddd22bcca94a'::uuid, 'technologie', '4e', 'Modes de représentation d’un OST', 'À quoi sert une vue éclatée d’un modèle 3D ?', 'mcq', '["À comprendre l’assemblage des pièces","À calculer le prix de revient","À programmer la carte","À coter les dimensions réelles"]'::jsonb, 0, 'Les pièces écartées les unes des autres montrent comment elles s’assemblent.', 4),
    ('ae3fcb66-102e-5532-88f0-8d061db37a6e'::uuid, 'technologie', '5e', 'Les mécanismes de transmission et de transformation de mouvements', 'Quel mécanisme transforme une rotation en translation lente et puissante, comme dans un étau ?', 'mcq', '["Le pignon-crémaillère","La vis-écrou","La bielle-manivelle","Les roues de friction"]'::jsonb, 1, 'La vis-écrou avance peu à chaque tour, mais avec beaucoup de force : étau, presse.', 1),
    ('56534dc2-1e1d-5211-9edb-a4b1c0e17799'::uuid, 'technologie', '5e', 'Les mécanismes de transmission et de transformation de mouvements', 'Dans quel sens tournent les deux pignons reliés par la chaîne d’un vélo ?', 'mcq', '["En sens inverse","Alternativement dans un sens puis dans l’autre","Dans le même sens","Cela dépend du nombre de dents"]'::jsonb, 2, 'Avec une chaîne, les pignons tournent dans le même sens ; deux engrenages en contact direct tournent en sens inverse.', 2),
    ('fe29022a-cdea-5344-82e3-3e2254a07bb9'::uuid, 'technologie', '5e', 'Les mécanismes de transmission et de transformation de mouvements', 'Un pignon d’entrée de 20 dents entraîne une roue de sortie de 60 dents. Que vaut le rapport de transmission ?', 'mcq', '["3","40","1/40","1/3"]'::jsonb, 3, 'r = dents de l’entrée ÷ dents de la sortie = 20 ÷ 60 = 1/3 : r < 1, c’est un réducteur.', 3),
    ('f3e0fd3e-915b-57ef-9622-b964698c12fa'::uuid, 'technologie', '5e', 'Les mécanismes de transmission et de transformation de mouvements', 'Quel mécanisme actionne les soupapes d’un moteur ?', 'mcq', '["Came et poussoir","Poulies-courroie","Pignons-chaîne","Engrenages"]'::jsonb, 0, 'La came transforme la rotation en translation alternative du poussoir, qui ouvre et ferme la soupape.', 4),
    ('ef1cd0c3-5127-5a40-97e2-b1b841304ec0'::uuid, 'technologie', '4e', 'Écrire mettre au point et exécuter un programme simple', 'Un programme s’arrête en cours de route à cause d’une division par zéro. De quelle erreur s’agit-il ?', 'mcq', '["Une erreur de syntaxe","Une erreur de logique","Une erreur d’exécution","Une erreur d’ergonomie"]'::jsonb, 2, 'Le programme a démarré, puis s’arrête : c’est une erreur d’exécution, comme un capteur absent.', 1),
    ('dbf10a2e-d7c8-50f3-8b16-bccd71bf3559'::uuid, 'technologie', '4e', 'Écrire mettre au point et exécuter un programme simple', 'Quel nom de variable est le plus explicite ?', 'mcq', '["v2","x","a1","vitesse"]'::jsonb, 3, 'Un nom explicite rend le programme lisible par un autre, ou par soi-même trois mois plus tard.', 2),
    ('bacb3501-e775-515a-b03a-56d0cbbd3ec2'::uuid, 'technologie', '4e', 'Écrire mettre au point et exécuter un programme simple', 'Quelle technique aide à voir où le comportement d’un programme dévie ?', 'mcq', '["Supprimer les commentaires","Afficher les valeurs intermédiaires","Raccourcir les noms de variables","Relancer sans rien changer"]'::jsonb, 1, 'Afficher les valeurs en cours de route, ou exécuter pas à pas, montre l’endroit exact où le programme s’écarte de l’attendu.', 3),
    ('e222a8d4-f092-5440-8b03-4d02f20e9fc2'::uuid, 'technologie', '4e', 'Écrire mettre au point et exécuter un programme simple', 'Que contient un bon jeu d’essai ?', 'mcq', '["Un cas normal, un cas limite et un cas interdit","Uniquement des cas qui fonctionnent","Un seul cas bien choisi","Les cas proposés par l’utilisateur, sans plus"]'::jsonb, 0, 'Le cas normal vérifie le fonctionnement, le cas limite et le cas interdit révèlent les défauts.', 4),
    ('5691cf9f-b36e-591a-b319-d2d6a5cf2549'::uuid, 'technologie', '4e', 'Prototypage de solutions', 'Quel degré de prototype valide le procédé de fabrication autant que l’objet ?', 'mcq', '["La maquette","Le prototype fonctionnel","La présérie","Le croquis"]'::jsonb, 2, 'La présérie utilise déjà les matériaux et les procédés du produit final.', 1),
    ('3a8b1cba-f54c-5c00-868c-ef6a37976742'::uuid, 'technologie', '4e', 'Prototypage de solutions', 'Quel moyen permet de prototyper l’électronique sans soudure ?', 'mcq', '["La découpe vinyle","Le carton plume","L’impression 3D","Les cartes programmables et les modules enfichables"]'::jsonb, 3, 'Les modules s’enfichent sur la carte : on peut tester et modifier le montage en quelques minutes.', 2),
    ('756d81f9-987d-57ef-8585-d4d92b15dffe'::uuid, 'technologie', '4e', 'Prototypage de solutions', 'Combien coûte une erreur découverte sur dix mille exemplaires vendus, par rapport à la même erreur trouvée sur un prototype ?', 'mcq', '["Deux fois plus","Cent fois plus","Dix fois moins","Autant"]'::jsonb, 1, 'Plus une erreur est découverte tard, plus elle coûte : c’est pour cela qu’on prototype avant de produire.', 3),
    ('b6464330-97c4-532c-bc3e-1418a980b70f'::uuid, 'technologie', '4e', 'Prototypage de solutions', 'Que faut-il noter en documentant un prototype ?', 'mcq', '["Photos, mesures, difficultés, modifications et leurs raisons","Seulement le résultat final","Seulement le coût","Seulement les photos"]'::jsonb, 0, 'Cette mémoire du projet nourrit le dossier final et explique chaque choix.', 4),
    ('299fbb05-0337-5531-b479-7c8ecc2c6a44'::uuid, 'technologie', '4e', 'Bases de la programmation', 'Quelle différence y a-t-il entre un algorithme et un programme ?', 'mcq', '["L’algorithme est toujours plus long","Le programme ne contient jamais de boucle","Le programme est la traduction de l’algorithme dans un langage compris par la machine","Il n’y en a aucune"]'::jsonb, 2, 'L’algorithme est la suite d’instructions ; le programme l’écrit dans un langage que la machine exécute.', 1),
    ('72e2d718-de20-5c2b-9cee-76addf45a6b3'::uuid, 'technologie', '4e', 'Bases de la programmation', 'Quelle boucle convient pour « répéter tant que le bouton n’est pas appuyé » ?', 'mcq', '["Une boucle bornée","Une boucle non bornée","Une séquence","Une variable"]'::jsonb, 1, 'On ne connaît pas d’avance le nombre de tours : la boucle est non bornée.', 2),
    ('b37cb1e5-ca4c-5a86-b6f6-8336bf61e9e3'::uuid, 'technologie', '4e', 'Bases de la programmation', 'Dans un organigramme, quelle forme représente un test ?', 'mcq', '["Le rectangle","La flèche","Le cercle","Le losange"]'::jsonb, 3, 'Losanges pour les tests, rectangles pour les actions, flèches pour l’enchaînement.', 3),
    ('0dd0d328-f111-5237-8c48-fdcb028d1312'::uuid, 'technologie', '4e', 'Bases de la programmation', 'Pour un programme, un capteur est…', 'mcq', '["une entrée, que le programme lit","une sortie, que le programme commande","une variable","un opérateur logique"]'::jsonb, 0, 'Le programme lit les capteurs (entrées) et commande les actionneurs (sorties) : c’est le lien avec la chaîne d’information.', 4),
    ('edebcab6-002f-5c02-931f-780a15849313'::uuid, 'technologie', '5e', 'Règles de sécurité', 'Que signifie un pictogramme carré vert ?', 'mcq', '["Une interdiction","Un danger","Une information de secours","Une obligation"]'::jsonb, 2, 'Le carré vert signale une issue de secours ou une trousse de premiers soins.', 1),
    ('57e15bf2-9d05-5ca1-9209-a2af9204598c'::uuid, 'technologie', '5e', 'Règles de sécurité', 'De quelles couleurs est le bouton d’arrêt d’urgence ?', 'mcq', '["Vert sur fond blanc","Rouge sur fond jaune","Bleu sur fond rouge","Noir sur fond jaune"]'::jsonb, 1, 'Rouge sur fond jaune, il coupe immédiatement l’alimentation de la machine.', 2),
    ('17aefccd-cbaf-5f23-9021-af6ebbb32065'::uuid, 'technologie', '5e', 'Règles de sécurité', 'Quelle tenue est exigée en atelier ?', 'mcq', '["Des gants en permanence","Une écharpe pour se protéger","Des sandales pour être à l’aise","Cheveux attachés, aucun bijou ni écharpe"]'::jsonb, 3, 'Cheveux, bijoux et écharpes peuvent être happés par une pièce en rotation ; il faut aussi une blouse et des chaussures fermées.', 3),
    ('2c2be284-5fc7-5fef-a339-f113b8c95c18'::uuid, 'technologie', '5e', 'Règles de sécurité', 'Que faut-il faire si l’on remarque un câble abîmé sur une machine ?', 'mcq', '["Le signaler","Continuer en faisant attention","Le réparer soi-même avec du ruban adhésif","L’ignorer si la machine fonctionne"]'::jsonb, 0, 'Toute anomalie — câble abîmé, bruit inhabituel — se signale avant de continuer.', 4),
    ('a1bb8d12-31e8-5358-abbc-e83571ffad7b'::uuid, 'technologie', '4e', 'Critères de choix d’un OST', 'Quelle est la dernière étape d’un tableau multicritère ?', 'mcq', '["Noter chaque case","Additionner les totaux pondérés","Choisir les solutions à comparer","Dessiner chaque solution"]'::jsonb, 1, 'On note les cases, on affecte les coefficients, puis on additionne les totaux pondérés pour départager les solutions.', 1),
    ('85ea3e1a-7d23-5411-902e-00d47c82d0c7'::uuid, 'technologie', '4e', 'Critères de choix d’un OST', 'Par rapport à une ampoule à filament, une LED…', 'mcq', '["coûte moins cher à l’achat et dure moins longtemps","consomme sept fois plus","coûte plus cher à l’achat mais consomme peu et dure bien plus longtemps","a la même durée de vie"]'::jsonb, 2, 'Son prix d’achat est plus élevé, mais sa faible consommation et sa durée de vie la rendent moins chère au coût global.', 2),
    ('8a27fb32-f088-580c-ae25-7ea832fc313c'::uuid, 'technologie', '4e', 'Critères de choix d’un OST', 'Quelle question pose le critère d’encombrement ?', 'mcq', '["Combien de temps sans panne ?","Est-il conforme aux normes ?","Est-il facile à utiliser ?","Tient-il dans l’espace disponible ?"]'::jsonb, 3, 'L’encombrement et la masse vérifient que l’objet trouve sa place ; la fiabilité, l’ergonomie et la sécurité posent les autres questions.', 3),
    ('abc5f38e-c4da-58f2-ba33-45fbef4f0e5d'::uuid, 'technologie', '4e', 'Critères de choix d’un OST', 'Sur quels critères une solution doit-elle d’abord atteindre le niveau exigé ?', 'mcq', '["Les critères impératifs (F0)","Les critères esthétiques","Les critères négociables (F2)","Le seul critère du prix"]'::jsonb, 0, 'Une solution qui manque un critère F0 est écartée, quel que soit son score ailleurs.', 4),
    ('69a46b14-e9a8-5dad-a36f-f7618092eb5e'::uuid, 'technologie', '5e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Quel essai consiste à charger une pièce en son milieu, appuyée à ses extrémités ?', 'mcq', '["L’essai de traction","L’essai de compression","L’essai de flexion","L’essai de torsion"]'::jsonb, 2, 'La flexion fait plier la pièce ; la traction l’étire, la compression l’écrase, la torsion la vrille.', 1),
    ('ff93c726-691b-5047-9bf3-c1a58a2deee1'::uuid, 'technologie', '5e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Pourquoi note-t-on l’incertitude d’une mesure ?', 'mcq', '["Pour rendre le résultat plus précis","Parce qu’une mesure sans incertitude n’en est pas une","Parce qu’elle remplace les conditions d’essai","Pour éviter de refaire l’essai"]'::jsonb, 1, 'Toute mesure a une marge d’erreur : sans elle, on ne peut pas juger si l’exigence est vraiment atteinte.', 2),
    ('edb7ba12-fd85-5eb4-b2bd-e708d71e0d7a'::uuid, 'technologie', '5e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Lequel de ces essais est un essai de performance ?', 'mcq', '["L’essai de traction","L’essai de torsion","L’essai de fatigue","La mesure de l’autonomie"]'::jsonb, 3, 'L’autonomie, la vitesse ou le niveau sonore sont des performances ; les trois autres sont des essais de tenue mécanique.', 3),
    ('68c7396f-e2b3-5c8c-8d34-d3b0df502f69'::uuid, 'technologie', '5e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Quel verdict écrit-on pour chaque exigence, à la fin d’une validation ?', 'mcq', '["Conforme ou non conforme","Bon ou mauvais","Rapide ou lent","Cher ou bon marché"]'::jsonb, 0, 'On compare la valeur mesurée au niveau exigé et on conclut : conforme ou non conforme.', 4),
    ('c99ccc7d-3686-5885-a4f9-f09536b112c5'::uuid, 'technologie', '5e', 'Concevoir et fabriquer un OST', 'Quel outil sert à choisir entre plusieurs solutions ?', 'mcq', '["Un diagramme de Gantt","Un tableau multicritère pondéré","Une nomenclature","Une gamme de fabrication"]'::jsonb, 1, 'Le tableau multicritère compare les solutions sur les critères du cahier des charges, avec une justification.', 1),
    ('caa19ae6-2098-5c84-bc61-6c90686cda8c'::uuid, 'technologie', '5e', 'Concevoir et fabriquer un OST', 'Un matériau devient indisponible : vers quelle étape la démarche renvoie-t-elle ?', 'mcq', '["La fabrication","Les tests","Le choix des solutions","La documentation finale"]'::jsonb, 2, 'La démarche est itérative : un test raté renvoie à la conception, un matériau indisponible au choix des solutions.', 2),
    ('e86d00be-ebbc-5da0-81db-32e400c446a8'::uuid, 'technologie', '5e', 'Concevoir et fabriquer un OST', 'Quel document de la documentation finale rend compte de l’impact du cycle de vie ?', 'mcq', '["La notice d’utilisation","La nomenclature","Le programme commenté","Le bilan environnemental"]'::jsonb, 3, 'Le bilan environnemental complète les plans, la nomenclature, le programme et la notice.', 3),
    ('764c5289-82b2-55d7-be51-275809243326'::uuid, 'technologie', '5e', 'Concevoir et fabriquer un OST', 'À quelle étape choisit-on les procédés, les machines, les outils et les règles de sécurité ?', 'mcq', '["La préparation de la fabrication","L’analyse du besoin","La recherche de solutions","La validation"]'::jsonb, 0, 'On prépare la fabrication, avec sa gamme d’opérations, avant de fabriquer et d’assembler.', 4),
    ('7d4086c1-d766-5e1a-b6bb-1eed0c198b3b'::uuid, 'technologie', '5e', 'Structuration et traitement des données', 'Dans un tableau de données, que représente une colonne ?', 'mcq', '["Un enregistrement","Un champ","Une clé","Un filtre"]'::jsonb, 1, 'Une colonne est un champ (nom, date, valeur) ; une ligne est un enregistrement.', 1),
    ('04717ad7-bc5d-5e34-9e4c-4f56a4a17b83'::uuid, 'technologie', '5e', 'Structuration et traitement des données', 'Quel type de données permet de tester « vrai » ou « faux » ?', 'mcq', '["Le texte","La date","Le nombre décimal","Le booléen"]'::jsonb, 3, 'Un booléen ne prend que deux valeurs, vrai ou faux : il sert aux tests.', 2),
    ('7bfa59a6-55a8-5639-be49-c4dfcfbcd36b'::uuid, 'technologie', '5e', 'Structuration et traitement des données', 'Quel graphique montre une répartition, les parts d’un tout ?', 'mcq', '["La courbe","L’histogramme","Le camembert","Le nuage de points"]'::jsonb, 2, 'Le camembert raconte une répartition ; la courbe une évolution, l’histogramme une comparaison.', 3),
    ('308e783c-94d4-51af-888d-eb95b85a73f3'::uuid, 'technologie', '5e', 'Structuration et traitement des données', 'Quel format d’échange organise les données en couples nom-valeur ?', 'mcq', '["JSON","CSV","JPEG","MP3"]'::jsonb, 0, 'Le JSON est très utilisé par les objets connectés et les sites web ; le CSV est un tableau en texte.', 4),
    ('30751c45-304a-59df-9844-5d0f95591b4f'::uuid, 'technologie', '4e', 'Concevoir et fabriquer un OST', 'Quel outil sert à choisir entre plusieurs solutions ?', 'mcq', '["Un diagramme de Gantt","Un tableau multicritère pondéré","Une nomenclature","Une gamme de fabrication"]'::jsonb, 1, 'Le tableau multicritère compare les solutions sur les critères du cahier des charges, avec une justification.', 1),
    ('53ea859e-9964-5ab9-9013-03c4c56d0165'::uuid, 'technologie', '4e', 'Concevoir et fabriquer un OST', 'Un matériau devient indisponible : vers quelle étape la démarche renvoie-t-elle ?', 'mcq', '["La fabrication","Les tests","Le choix des solutions","La documentation finale"]'::jsonb, 2, 'La démarche est itérative : un test raté renvoie à la conception, un matériau indisponible au choix des solutions.', 2),
    ('36f22347-b6b7-5ccd-aecc-7879ef58e168'::uuid, 'technologie', '4e', 'Concevoir et fabriquer un OST', 'Quel document de la documentation finale rend compte de l’impact du cycle de vie ?', 'mcq', '["La notice d’utilisation","La nomenclature","Le programme commenté","Le bilan environnemental"]'::jsonb, 3, 'Le bilan environnemental complète les plans, la nomenclature, le programme et la notice.', 3),
    ('ac6f9217-6c99-5c2b-991e-69fa27ab36dd'::uuid, 'technologie', '4e', 'Concevoir et fabriquer un OST', 'À quelle étape choisit-on les procédés, les machines, les outils et les règles de sécurité ?', 'mcq', '["La préparation de la fabrication","L’analyse du besoin","La recherche de solutions","La validation"]'::jsonb, 0, 'On prépare la fabrication, avec sa gamme d’opérations, avant de fabriquer et d’assembler.', 4),
    ('2c6e6d03-2be0-50c9-809e-5af9c983b398'::uuid, 'technologie', '4e', 'La circulation de l’information dans un réseau informatique', 'Quel équipement relie les machines d’un même réseau local et aiguille les messages ?', 'mcq', '["Le routeur","Le DNS","Le switch","Le modem"]'::jsonb, 2, 'Le switch travaille dans un même réseau ; le routeur relie deux réseaux différents.', 1),
    ('d855c409-f0fd-5abd-9770-b035249b54be'::uuid, 'technologie', '4e', 'La circulation de l’information dans un réseau informatique', 'Quel protocole sert au courrier électronique ?', 'mcq', '["HTTP","FTP","HTTPS","SMTP"]'::jsonb, 3, 'SMTP transporte le courrier ; HTTP et HTTPS servent le web, FTP le transfert de fichiers.', 2),
    ('c3480c6c-f831-569a-b446-e4d9ac43e431'::uuid, 'technologie', '4e', 'La circulation de l’information dans un réseau informatique', 'Que se passe-t-il si un paquet manque à l’arrivée ?', 'mcq', '["Il est redemandé","Tout le message est perdu","Le routeur le reconstitue au hasard","L’ordinateur s’arrête"]'::jsonb, 0, 'Les paquets numérotés sont réassemblés à l’arrivée, et un paquet manquant est redemandé.', 3),
    ('3d7628a2-2d17-5042-9a55-d8eb0b89f939'::uuid, 'technologie', '4e', 'La circulation de l’information dans un réseau informatique', 'Comment appelle-t-on la machine qui demande un service à un serveur ?', 'mcq', '["Le routeur","Le client","Le switch","La box"]'::jsonb, 1, 'Le serveur rend un service, le client le demande : c’est le cas de ton navigateur face à un site web.', 4),
    ('2eca0816-8e89-51e5-804f-be35ce54035c'::uuid, 'technologie', '5e', 'Organisation d’un projet technique', 'Que porte l’axe horizontal d’un diagramme de Gantt ?', 'mcq', '["Les tâches","Le temps","Les coûts","Les responsables"]'::jsonb, 1, 'Le temps est en abscisse, les tâches en ordonnée ; la longueur de chaque barre est la durée de la tâche.', 1),
    ('60060264-3864-5c60-9df3-d3030a595451'::uuid, 'technologie', '5e', 'Organisation d’un projet technique', 'De quoi dispose une tâche qui n’est pas sur le chemin critique ?', 'mcq', '["D’un budget supplémentaire","D’une priorité absolue","D’une marge","D’aucun responsable"]'::jsonb, 2, 'Elle peut prendre un peu de retard sans décaler la fin du projet, ce qui est impossible sur le chemin critique.', 2),
    ('d6995911-6ae9-571c-a265-23e1b0393764'::uuid, 'technologie', '5e', 'Organisation d’un projet technique', 'Quelle phase vient juste après l’analyse du besoin ?', 'mcq', '["La réalisation","Le bilan","La conception","La recherche de solutions"]'::jsonb, 3, 'Après le cahier des charges, on cherche et compare plusieurs pistes, avant de concevoir.', 3),
    ('465ac8f1-3524-56ba-b074-5c4a7e101008'::uuid, 'technologie', '5e', 'Organisation d’un projet technique', 'Quel document garde les décisions et les essais ratés d’un projet ?', 'mcq', '["Le carnet de bord","Le diagramme de Gantt","La nomenclature","Le cahier des charges"]'::jsonb, 0, 'Le carnet de bord assure la traçabilité : il évite qu’un autre refasse la même erreur.', 4),
    ('97cbc495-979b-540e-b3c0-5475c8c83cba'::uuid, 'technologie', '4e', 'Les OST', 'Pour une lampe de lecture, quelle est la matière d’œuvre ?', 'mcq', '["Le verre de l’ampoule","L’électricité du réseau","La lumière de la pièce","La personne qui lit"]'::jsonb, 2, 'La matière d’œuvre est ce sur quoi l’objet agit : la lampe modifie la lumière de la pièce. Celui qui lit est l’utilisateur.', 1),
    ('f869a408-2481-5a50-b194-4ae2ddba629b'::uuid, 'technologie', '4e', 'Les OST', 'Lequel de ces exemples est un système technique ?', 'mcq', '["Un tournevis","Une chaise","Un marteau","Un ascenseur"]'::jsonb, 3, 'Un ascenseur associe plusieurs objets qui travaillent ensemble, avec électronique et programme ; les trois autres répondent au besoin par eux-mêmes.', 2),
    ('ccccec92-2277-5771-8f43-1b0c717749c5'::uuid, 'technologie', '4e', 'Les OST', 'Quelle fonction d’usage le vélo garde-t-il depuis 150 ans ?', 'mcq', '["Se déplacer","Freiner","Transmettre le mouvement","Éclairer"]'::jsonb, 0, 'Sa fonction d’usage n’a pas changé ; ses matériaux, sa transmission, ses freins et son assistance électrique, si.', 3),
    ('d58334d6-a754-53a0-a994-caf783cdfb8d'::uuid, 'technologie', '4e', 'Les OST', 'La bougie, la lampe à huile, l’ampoule et la LED forment…', 'mcq', '["une lignée d’objets techniques","une famille d’objets techniques","un système technique","une chaîne d’énergie"]'::jsonb, 1, 'Ils remplissent la même fonction d’usage, éclairer, par des solutions différentes : c’est une famille.', 4),
    ('7518db88-e708-566b-8f32-14e73aebe1bc'::uuid, 'technologie', '5e', 'Système d’information et stockage de données', 'Combien de bits compte un octet ?', 'mcq', '["8","2","10","16"]'::jsonb, 0, 'Un octet vaut 8 bits et code à peu près un caractère.', 1),
    ('a1d4b2f0-592c-51f0-92b8-4208fc8eee64'::uuid, 'technologie', '5e', 'Système d’information et stockage de données', 'Qu’apporte l’authentification à deux facteurs ?', 'mcq', '["Elle chiffre le disque","Elle double l’espace de stockage","Le mot de passe seul ne suffit plus pour entrer dans le compte","Elle supprime le mot de passe"]'::jsonb, 2, 'Un second élément, comme un code reçu sur le téléphone, est exigé : un mot de passe volé ne suffit plus.', 2),
    ('dffdd6af-f9fc-5094-9fc0-26685d6b89f4'::uuid, 'technologie', '5e', 'Système d’information et stockage de données', 'Quelle est la limite d’un stockage dans le nuage ?', 'mcq', '["Il n’est accessible que d’un seul endroit","Il ne peut pas être sauvegardé","Il est interdit par le RGPD","Il dépend du réseau et du prestataire"]'::jsonb, 3, 'Accessible de partout, il exige une connexion et dépend d’un prestataire, dont les centres de données sont bien réels.', 3),
    ('a48c7fc1-8450-531c-a585-6c2792a4af57'::uuid, 'technologie', '5e', 'Système d’information et stockage de données', 'Quel principe du RGPD impose de dire à quoi serviront les données collectées ?', 'mcq', '["Le consentement","La finalité","La durée de conservation","Le droit de rectification"]'::jsonb, 1, 'La finalité de la collecte doit être déclarée ; le consentement, lui, doit être explicite.', 4),
    ('48ad0bbe-dda1-5055-9093-e7e3fcd58131'::uuid, 'technologie', '4e', 'La chaîne d’information', 'Quel composant acquiert une information sur la lumière ambiante ?', 'mcq', '["Le buzzer","La photorésistance","Le microcontrôleur","Le moteur"]'::jsonb, 1, 'La photorésistance est un capteur de lumière : elle assure la fonction « acquérir ».', 1),
    ('f04c4544-d826-5319-97b2-c3e59b75fee5'::uuid, 'technologie', '4e', 'La chaîne d’information', 'Quelle fonction de la chaîne d’information assure un buzzer ?', 'mcq', '["Acquérir","Traiter","Communiquer","Alimenter"]'::jsonb, 2, 'Il transmet une information à l’utilisateur par un son, comme l’écran ou la LED.', 2),
    ('de934780-3fd0-5508-89ad-4349305d9683'::uuid, 'technologie', '4e', 'La chaîne d’information', 'Qu’exécute la partie commande pour décider quoi faire ?', 'mcq', '["Une conversion d’énergie","Une mesure","Un signal lumineux","Un programme"]'::jsonb, 3, 'Le microcontrôleur, la carte programmable ou l’automate exécutent un programme : c’est la fonction « traiter ».', 3),
    ('85eaf421-fbee-50e2-899b-001228a22e71'::uuid, 'technologie', '4e', 'La chaîne d’information', 'Lequel de ces moyens permet de communiquer sans fil ?', 'mcq', '["Le Bluetooth","Le fin de course","La thermistance","Le vérin"]'::jsonb, 0, 'Le Bluetooth, le Wi-Fi ou la radio transmettent l’information à un autre système ; le fin de course et la thermistance sont des capteurs.', 4),
    ('19c96be7-14d5-564d-ac4c-08dcbbae8c99'::uuid, 'technologie', '5e', 'Modes de représentation d’un OST', 'Que signifie une échelle 2:1 ?', 'mcq', '["Le dessin est deux fois plus petit que l’objet","Le dessin est deux fois plus grand que l’objet","Le dessin est à taille réelle","L’objet mesure 2 cm"]'::jsonb, 1, 'Le premier nombre concerne le dessin : 2:1 agrandit deux fois, 1:2 réduit deux fois, 1:1 est la grandeur nature.', 1),
    ('ae30b746-6e31-5825-a62a-262aaed4238f'::uuid, 'technologie', '5e', 'Modes de représentation d’un OST', 'Quel trait représente un axe sur un dessin technique ?', 'mcq', '["Le trait continu fort","Le trait interrompu","Le trait mixte fin","Le trait ondulé"]'::jsonb, 2, 'Le trait continu fort montre une arête vue, l’interrompu une arête cachée, le mixte fin un axe.', 2),
    ('b9db0a0c-0316-50ee-8afa-b9b7de20c5d7'::uuid, 'technologie', '5e', 'Modes de représentation d’un OST', 'Quel schéma représente les composants normalisés d’un circuit ?', 'mcq', '["Le schéma de principe","Le schéma cinématique","Le croquis","Le schéma électrique"]'::jsonb, 3, 'Le schéma électrique utilise les symboles normalisés des composants ; le cinématique montre les liaisons et les mouvements.', 3),
    ('a3fb59e9-6e9f-5fdf-89aa-920fa965b402'::uuid, 'technologie', '5e', 'Modes de représentation d’un OST', 'À quoi sert une vue éclatée d’un modèle 3D ?', 'mcq', '["À comprendre l’assemblage des pièces","À calculer le prix de revient","À programmer la carte","À coter les dimensions réelles"]'::jsonb, 0, 'Les pièces écartées les unes des autres montrent comment elles s’assemblent.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

-- 3. Sonde finale ---------------------------------------------------------
DO $$
